/**
 * dsh-mcp-manager — catalog/impl/cache-view/index.ts：注入端目录缓存视图（#664 阶段 5）。
 *
 * 自 src/manager.ts 迁出（catalog 域）：合成注入端目录缓存视图——以 B
 * （supervisor 摘要缓存）为基底，逐服务器按「scope + 模式」用中间层目录摘要
 * 覆盖（#569 修复核心）。diskCatalogSummaryCache（mtime 缓存）随迁，以工厂
 * 闭包持有（防多实例共享串状态）；宿主最小面 CatalogViewHost 解耦 manager
 * 细节（C-DIR：catalogViewFor 私有缓存随迁，薄桥接）。
 */

import { existsSync, statSync } from "node:fs";
import { catalogSummaryFile } from "../../../shared/interface.ts";
import type { McpMiddleware } from "../../../connection/runtime/interface.ts";
import type { ServerConfig } from "../../../config/interface.ts";
import { MIDDLEWARE_GLOBAL_ROOT, SCOPE_PROJECT } from "../../../../shared/interface.ts";
import { catalogDirectory } from "../directory/index.ts";
import { catalogPorts } from "../service/index.ts";
import { summarizeToolDescriptions } from "../entries/index.ts";
import type { CatalogCache } from "../entries/index.ts";

/**
 * 目录摘要缓存文件（连接成功时把工具描述摘要持久化于此；目录 digest 的稳定数据源）。
 * 名字与权限的物理定义在 server/shared/paths.ts（I7 单源）。
 */
export function catalogCacheFile() {
  return catalogSummaryFile();
}

/** catalogViewFor 的宿主最小面（manager 提供；实例经读取器取——apply 完成后恒在，pre-step 窗口未装配时返回 undefined 走 B 兜底）。 */
export interface CatalogViewHost {
  getCatalogCache(): CatalogCache;
  getMiddleware(): McpMiddleware | undefined;
  catalogCachePathFor(root: string): string;
}

/** 注入端目录缓存视图解析器（makeCatalogViewFor 产物）。 */
export type CatalogViewResolver = (
  cwd: string | undefined,
  servers: Map<string, { server: ServerConfig; scope: string }>,
) => Promise<CatalogCache>;

/**
 * 合成注入端目录缓存视图（#569 修复核心）：以 B（supervisor 摘要缓存）为基底，
 * 逐服务器按「scope + 模式」用中间层目录摘要覆盖——修复「middleware 采集的
 * 工具摘要注入端读不到」：
 * - 用户手写 server.description 由 composeCatalogEntries 处理（优先级最高），
 *   不在此视图内；
 * - 本视图只负责注入端的 ②（中间层目录摘要）与 ③（B 缓存摘要）两级回退；
 * - **判 middleware 实例**（apply 完成后恒在；实例缺失＝pre-step 窗口尚未装配 → 全部走 B）。
 *
 * root 映射（单池后与单元表同口径）：
 * - scope=project → 该 cwd 归一化项目 root 的单元 → 无则磁盘 last-good；
 * - scope=global → @global 单元/磁盘 → 仍无则保留 B。
 * 严格按 scope 解析、不跨 scope 混配同名服务器（防不同配置被错配）。
 * 单元不存在时读磁盘 last-good（带 mtime 缓存），**不主动 projectUnitFor**
 * ——pre-step 无连接副作用。
 *
 * diskCatalogSummaryCache（root → server → { mtimeMs, summary }）在闭包内
 * 持有：防 pre-step 每轮重复读盘解析（目录文件最大 ~256KB，JSON parse 有成本）。
 */
export function makeCatalogViewFor(host: CatalogViewHost): CatalogViewResolver {
  const diskCatalogSummaryCache = new Map<
    string,
    Map<string, { mtimeMs: number; summary: string | undefined }>
  >();

  /** 查中间层单服务器目录摘要：内存单元优先，单元缺失/无该服务器 → 磁盘
   * last-good 兜底（带 mtime 缓存，防 pre-step 每轮读盘）。返回 undefined
   * 表示中间层无此服务器数据（调用方保留 B 兜底）。 */
  async function middlewareCatalogSummary(
    mw: McpMiddleware,
    root: string,
    name: string,
  ): Promise<string | undefined> {
    const {
      store: { readCatalogServerFromDisk },
    } = catalogPorts.get();
    const catalog = catalogDirectory.entryFor(root, name);
    const tools = catalog?.tools;
    if (tools !== undefined && tools.size > 0 && catalog?.unavailable === undefined) {
      // 内存目录（已含磁盘 last-good：单元创建时 ensureRootLoaded 载入）→ 直接聚合。
      return summarizeToolDescriptions(tools as Map<string, { description?: unknown }>);
    }
    // 内存无该服务器数据（单元未建 / 条目缺失 / 发现失败）→ 磁盘 last-good 兜底。
    const file = host.catalogCachePathFor(root);
    const cachedRoot = diskCatalogSummaryCache.get(root);
    const cached = cachedRoot?.get(name);
    let mtimeMs = 0;
    try {
      if (!existsSync(file)) return undefined;
      const stat = statSync(file);
      mtimeMs = stat.mtimeMs;
    } catch {
      return undefined; // 文件消失/不可读 → 无磁盘兜底
    }
    if (cached?.mtimeMs === mtimeMs) return cached.summary;
    const persisted = await readCatalogServerFromDisk(file, name);
    if (persisted === undefined) return undefined;
    const summary = summarizeToolDescriptions(
      new Map(persisted.tools.map((tool) => [tool.name, { description: tool.description }])),
    );
    let rootCache = diskCatalogSummaryCache.get(root);
    if (rootCache === undefined) {
      rootCache = new Map();
      diskCatalogSummaryCache.set(root, rootCache);
    }
    rootCache.set(name, { mtimeMs, summary });
    return summary;
  }

  return async (cwd, servers): Promise<CatalogCache> => {
    const {
      workspace: { normalizedProjectRoot },
    } = catalogPorts.get();
    const catalogCache = host.getCatalogCache();
    const view: CatalogCache = new Map();
    for (const [name, entry] of catalogCache) view.set(name, { summary: entry.summary });
    const mw = host.getMiddleware();
    if (mw === undefined) return view;
    // 项目 root 只解析一次（所有 project scope 服务器共用；空 cwd → 无项目单元）。
    const cwdRoot =
      cwd === undefined || cwd === null || cwd === ""
        ? undefined
        : await normalizedProjectRoot(cwd);
    for (const [name, { scope }] of servers) {
      if (name === "") continue;
      // root 解析：project scope → 项目 root；global scope → @global。
      // 跨 scope 不混配（同名项目级/全局是两份配置）。
      const root = scope === SCOPE_PROJECT ? cwdRoot : MIDDLEWARE_GLOBAL_ROOT;
      if (root === undefined) continue;
      const summary = await middlewareCatalogSummary(mw, root, name);
      if (summary !== undefined) view.set(name, { summary });
    }
    return view;
  };
}

/**
 * dsh-mcp-manager — catalog/impl/digest/index.ts：目录条目 digest（#664 阶段 5）。
 *
 * 自 src/catalog.ts 拆出（digest 域）：sha256 摘要，**只含服务器集合（name），
 * 不含描述文本**——工具描述不稳定（按需注册/动态描述），含描述会永远追不上
 * 抖动触发替换注入；只含 name 后服务器增删才触发替换。
 */

import { createHash } from "node:crypto";
import type { CatalogEntry } from "../entries/index.ts";

/**
 * 目录条目 digest（sha256）——**只含服务器集合（name），不含描述文本**。
 *
 * 为什么：MCP 服务器的工具描述集合不稳定（按需注册/动态描述，实测 code-graph
 * 等服务器不同时刻的摘要都不同）。若 digest 含描述文本，缓存摘要一更新就触发
 * 替换注入——永远追不上抖动。digest 只含 name 后：
 * - 服务器增删 → digest 变 → 原位替换（合理）
 * - 描述/缓存更新 → digest 不变 → 本会话目录保持快照（静态能力地图语义，
 *   与消息声明"仅描述能力、不代表当前连接状态"一致），跨会话才反映新缓存
 */
export function digestCatalogEntries(entries: CatalogEntry[]): string {
  const canonical = entries.map((entry) => entry.name).join("\n");
  return createHash("sha256").update(canonical).digest("hex");
}

/**
 * dsh-mcp-manager — catalog/impl/directory/index.ts：工具目录内存态 + 投影 + last-good（#767 S1-3b）。
 *
 * 本块原先长在 connection/runtime/middleware.ts 的 McpMiddleware 上，与连接池共用一份实例状态；
 * 搬进来的理由（767-v6-STAGED-PLAN §2.6 裁定 A）：per-root 工具目录是「采集」的产物，采集与落盘
 * 分居两域会造出两个事实源。搬完后连接层只剩调用点，目录的写与读都经本块的实例。
 *
 * **宿主能力走入参契约而不是端口**（同 `CatalogViewHost` 的口径）：注册面视图、落盘路径与告警
 * 出口都由连接层在调用点构造递入——它们是连接的宿主面事实（`host.ctx.tools.schemas()` /
 * `host.catalogCachePath(root)` / `host.logger.warn`），本域只按值使用，不持有、不推导。
 *
 * 状态收进类实例字段而不是模块级 let：`gate:module-state` 明禁模块级可变状态（I9）。形态照
 * `catalog/impl/service` 的 CatalogPorts。
 */
import { randomBytes } from "node:crypto";
import { existsSync } from "node:fs";
import { mkdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import { dirname } from "node:path";
import type { CatalogServer, CatalogTool } from "../entries/type.ts";
import { catalogPorts } from "../service/index.ts";
import { fileMode, readJsonFile, writeFileAtomic } from "../../../shared/interface.ts";

/** 注册面视图：宿主 `ctx.tools.schemas()` 的返回形状（每次投影现取）。 */
export type SchemaView = ReadonlyArray<{
  name?: unknown;
  description?: unknown;
  parameters?: unknown;
}>;

/** 投影入参：id 前缀（`mcp__<id>__`）源自连接层的账本键，其余为本域要用的宿主面事实。 */
export interface RegisteredProjectionInput {
  root: string;
  serverName: string;
  id: string;
  /** 注册面视图（连接层现取宿主注册表）。 */
  schemas: SchemaView;
  /**
   * 落盘路径：连接层用 `host.catalogCachePath(root)` 算，本域不推路径。接 thunk 是为了
   * 保住「路径求值失败 = 投影失败（unavailable 降级）」这条既有语义——调用点把求值推后
   * 到这里，求值抛错才落在本层的 catch 内（先求值再传参会让异常逃出降级面）。
   */
  cachePath: () => string;
  /** 凭据脱敏：本域不持服务器表，故这一层由调用方（连接层）闭包给出。 */
  redact: (error: unknown) => string;
  /** runtime 注入条目（内存态）不落盘（#413）：判定同样归调用方。 */
  isRuntimeServer: (name: string) => boolean;
  /** 告警出口（连接层转 host.logger.warn）。 */
  warn: (message: string) => void;
}

/**
 * 目录 last-good 写盘（H2 等价接入，#767 S2-C 筆3）：登记路径（`catalog/<hash>.json`）
 * 经 file-io `writeFileAtomic`（mode 取登记表 + 同路径写串行 + 失败清理临时名）；
 * 未登记路径（单测 tmp 覆盖 `cachePath`）回落硬化直写（随机后缀 + 失败清理）——
 * `writeFileAtomic` 对未登记路径抛 I6，直接调等于把回落写盘变成 warn（store.save 的 S2-B 同式）。
 * 序列化形状由调用方给整串（`{ version: 1, root, entries }` + 2 空格）逐字节不变：序列化收敛不是本笔的事。
 *
 * 模块函数而非类成员/导出：调用点同文件，导出会进导出面快照（零 diff 要求）。 */
async function writeDirectoryCacheFile(file: string, data: string): Promise<void> {
  let registered = true;
  try {
    fileMode(file);
  } catch {
    registered = false;
  }
  if (registered) {
    await writeFileAtomic(file, data);
    return;
  }
  // R1/R2 同式硬化：回落临时名加随机后缀 + 失败清理（与 file-io `writeOnce` 同式）；
  // mode 沿既有回落形状（无 mode），只补唯一性与清理，不改写盘语义。
  const dir = dirname(file);
  if (!existsSync(dir)) await mkdir(dir, { recursive: true });
  const tmp = `${file}.${process.pid}.${Date.now().toString(36)}.${randomBytes(6).toString("hex")}.tmp`;
  try {
    await writeFile(tmp, data, "utf8");
    await rename(tmp, file);
  } catch (cause) {
    await rm(tmp, { force: true }).catch(() => undefined);
    throw cause;
  }
}

/**
 * 每 root 的工具目录内存态 + last-good 磁盘读写 + 注册面投影。
 *
 * 「root 在册」由独立的 root 集合承载：只有 root 在册、且某服务器在册时读口才作答。这条区分
 * 是必须的——「单元根本没有该 root」与「root 在册但没有该服务器」在消费点走的是不同分支
 * （detail 报未发现，而 search/list 只是没有命中）。
 */
class CatalogDirectory {
  /** root →（裸 server 名 → 目录条目）。 */
  private readonly byRoot = new Map<string, Map<string, CatalogServer>>();
  /** 在册 root 集合：与 byRoot 同步维护，承载「单元存在但目录为空」这一可区分状态。 */
  private readonly roots = new Set<string>();

  /** 读口：root 的整份目录；root 不在册 → undefined。域外只读，故给 ReadonlyMap。 */
  serversFor(root: string): ReadonlyMap<string, CatalogServer> | undefined {
    return this.byRoot.get(root);
  }

  /** 读口：单服务器条目；root 或服务器不在册 → undefined。 */
  entryFor(root: string, serverName: string): CatalogServer | undefined {
    return this.byRoot.get(root)?.get(serverName);
  }

  /** 读口：root 在册的服务器裸名表（A1 归因文案用）。 */
  serverNamesFor(root: string): readonly string[] {
    const servers = this.byRoot.get(root);
    return servers === undefined ? [] : [...servers.keys()];
  }

  /**
   * 读口：该 id 前缀下是否已有注册工具——「已连上」的唯一正向证据（官方零状态 API）。
   * 注册面视图按入参现给，本域不自己去取宿主注册表。
   */
  hasRegisteredTools(schemas: SchemaView, id: string): boolean {
    const prefix = `mcp__${id}__`;
    return schemas.some(
      (schema) => typeof schema?.name === "string" && schema.name.startsWith(prefix),
    );
  }

  /**
   * 装载 root 的 last-good 目录缓存（缺失/损坏 → 空）。
   *
   * root 已在册即短路：单元创建是唯一载入点，重复读盘会拿磁盘那份**盖掉**内存里更新的投影
   * （落盘是异步 fire-and-forget，内存态才是权威）。
   */
  async ensureRootLoaded(root: string, cachePath: string): Promise<void> {
    // 已在册即短路（含**先投影后建单元**的顺序：投影会就地建表，此时不再读盘覆盖）。
    if (this.byRoot.has(root)) return;
    const servers = new Map<string, CatalogServer>();
    this.byRoot.set(root, servers);
    this.roots.add(root);
    try {
      // H2 等价接入（#767 S2-C 筆3）：容错读经 file-io `readJsonFile`（缺失/不可读/
      // 是目录/坏 JSON 一律回落 null，与既有 existsSync+readFile+parse 的「缺失/损坏 → 空」同族）；
      // 形状校验与条目清洗逐条不变。
      const parsed = await readJsonFile<{ entries?: Record<string, unknown> } | null>(cachePath);
      if (
        parsed &&
        typeof parsed === "object" &&
        typeof parsed.entries === "object" &&
        parsed.entries !== null
      ) {
        for (const [serverName, entry] of Object.entries(parsed.entries)) {
          const rec = entry as { discoveredAt?: unknown; tools?: unknown } | undefined;
          if (typeof rec !== "object" || rec === null) continue;
          servers.set(serverName, {
            discoveredAt: typeof rec.discoveredAt === "number" ? rec.discoveredAt : 0,
            tools: parsePersistedTools(rec.tools),
          });
        }
      }
    } catch {
      // 损坏缓存忽略
    }
  }

  /** 注销 root 的内存目录（拆毁单元时调用）；root 从未在册则无动作。 */
  dropRoot(root: string): void {
    this.byRoot.delete(root);
    this.roots.delete(root);
  }

  /**
   * 注销单个服务器的内存目录条目（remove/update 配置变更后调用；#392 遗留①）。
   * @returns 是否真的删掉了条目——调用方据此决定要不要广播状态（与 `Map.delete` 同口径）。
   */
  dropServer(root: string, serverName: string): boolean {
    return this.byRoot.get(root)?.delete(serverName) ?? false;
  }

  /** 条目不可用（发现或落盘失败）：置空并带脱敏后的原因（unavailable 段）。 */
  markUnavailable(root: string, serverName: string, reason: string): void {
    // 只翻转已有条目：不存在的服务器不因「标记不可用」而在册（那是另一条语义）。
    const servers = this.byRoot.get(root);
    if (servers === undefined || !servers.has(serverName)) return;
    servers.set(serverName, {
      discoveredAt: 0,
      tools: new Map(),
      unavailable: reason,
    });
  }

  /**
   * 注册面 → per-root 目录的投影（裁定 W + 裁定 K）。
   *
   * 官方注册名是 `mcp__<id>__<tool>`，去掉前缀即裸名；description 与 parameters 都在注册面
   * 视图里，不需要第二份工具清单。fresh 短路：TTL 内不重投影（discover 惰性语义），且短路发生
   * 在任何落盘动作之前。落盘失败（含路径求值失败）由本层 catch 收口成 unavailable 降级。
   */
  async projectRegisteredTools(input: RegisteredProjectionInput): Promise<void> {
    const servers = this.byRoot.get(input.root);
    if (servers === undefined) return;
    if (isCatalogFresh(servers.get(input.serverName))) return; // fresh
    const prefix = `mcp__${input.id}__`;
    try {
      const tools: Array<{
        name: string;
        description: string;
        inputSchema: Record<string, unknown>;
      }> = [];
      for (const schema of input.schemas) {
        const name = schema?.name;
        if (typeof name !== "string" || !name.startsWith(prefix)) continue;
        tools.push({
          name: name.slice(prefix.length),
          description: typeof schema.description === "string" ? schema.description : "",
          inputSchema: (schema.parameters ?? {}) as Record<string, unknown>,
        });
      }
      servers.set(input.serverName, {
        discoveredAt: Date.now(),
        tools: boundCatalogTools(tools),
      });
      // 落盘失败由外层 catch 收口报错；不 await 会让失败变成未处理拒绝而不是日志
      await this.persistRoot(input.root, {
        cachePath: input.cachePath,
        isRuntimeServer: input.isRuntimeServer,
        warn: input.warn,
      });
    } catch (error) {
      this.markUnavailable(input.root, input.serverName, input.redact(error));
    }
  }

  /**
   * #413：从封装定义（toolDefinitions）投影目录，替代远端 discover。
   * 封装 execute 为调用方 JS 直呼（不经远端 MCP），目录数据源即调用方定义：
   * name/description 直取；dsh-tools 的 parameters（ToolSchema）即 JSON Schema
   * 形态，直接作 CatalogTool.inputSchema（与 supervisor 封装分支同口径）。
   */
  projectWrappedTools(input: {
    root: string;
    serverName: string;
    definitions: readonly unknown[];
  }): void {
    // root 未在册时就地建表：虚拟单元的投影是**纯内存写**，不依赖读盘完成（顺带避免
    // 「先写投影、后建单元」这一顺序下静默丢写）。
    let servers = this.byRoot.get(input.root);
    if (servers === undefined) {
      servers = new Map<string, CatalogServer>();
      this.byRoot.set(input.root, servers);
      this.roots.add(input.root);
    }
    servers.set(input.serverName, {
      discoveredAt: Date.now(),
      tools: wrappedToolsOf(input.definitions),
    });
  }

  /**
   * 目录 last-good 持久化（空采集不写盘；public 供测试与外部触发）。
   *
   * 路径求值由**调用方**给（连接层用 host.catalogCachePath(root) 算），写盘失败只 warn；
   * 路径求值失败按设计逃出本层、由投影的 catch 收口成 unavailable 降级。
   */
  async persistRoot(
    root: string,
    opts: {
      cachePath: () => string;
      isRuntimeServer: (name: string) => boolean;
      warn: (message: string) => void;
    },
  ): Promise<void> {
    const servers = this.byRoot.get(root);
    if (servers === undefined) return;
    let anyTools = false;
    const payload: Record<string, unknown> = {};
    for (const [serverName, entry] of servers) {
      // #413：runtime 注入条目（内存态，不落盘）目录只驻内存——防卸载/重启后
      // 幽灵条目被 ensureRootLoaded 载回（与 removeRootEntry 清理同类问题）。
      if (opts.isRuntimeServer(serverName)) continue;
      if (entry.tools.size === 0) continue;
      anyTools = true;
      payload[serverName] = {
        discoveredAt: entry.discoveredAt,
        tools: [...entry.tools.entries()].map(([name, tool]) => ({
          name,
          description: tool.description,
          inputSchema: tool.inputSchema,
        })),
      };
    }
    if (!anyTools) return;
    // 求值在 try 之外：路径求值失败是要被投影 catch 收口成 unavailable 的运行时错误。
    const cachePath = opts.cachePath();
    try {
      // H2 等价接入（#767 S2-C 筆3）：求值后 try 内写段经 `writeDirectoryCacheFile`
      // （登记路径走 `writeFileAtomic`，未登记回落硬化直写）；runtime 过滤/空采集早返/求值位置均不动。
      await writeDirectoryCacheFile(
        cachePath,
        JSON.stringify({ version: 1, root, entries: payload }, null, 2),
      );
    } catch (error) {
      opts.warn(`dsh-mcp-manager: catalog cache write failed: ${msgOf(error)}`);
    }
  }

  /**
   * 从磁盘 last-good 目录缓存中清除单服务器条目（remove/update 后调用；#392 遗留①）。
   * persistRoot 是全量覆盖且空采集不写盘——remove 后该 root 目录可能已空，若不显式
   * 清盘，磁盘缓存仍残留已删服务器条目，插件重启/@global 单元重建时 ensureRootLoaded
   * 把幽灵条目载回（ws_mcp_list 再次列出）。这里读现有缓存、删条目、写回；条目删空则
   * 删除缓存文件。内存目录由调用方（dropMiddlewareConnection）先行删除。
   */
  async removeRootEntry(
    root: string,
    serverName: string,
    opts: { cachePath: string; warn: (message: string) => void },
  ): Promise<void> {
    try {
      if (!existsSync(opts.cachePath)) return;
      const raw = await readFile(opts.cachePath, "utf8");
      const parsed = JSON.parse(raw) as {
        version?: unknown;
        root?: unknown;
        entries?: Record<string, unknown>;
      } | null;
      if (
        parsed === null ||
        typeof parsed !== "object" ||
        typeof parsed.entries !== "object" ||
        parsed.entries === null
      )
        return;
      if (!(serverName in parsed.entries)) return;
      delete parsed.entries[serverName];
      if (Object.keys(parsed.entries).length === 0) {
        await rm(opts.cachePath, { force: true }).catch(() => {});
        return;
      }
      // #903 crash 残留 tmp：失败分支 rm 清理 + 随机后缀（与 file-io 同式）。
      const tmp = `${opts.cachePath}.${process.pid}.${Date.now().toString(36)}.${randomBytes(6).toString("hex")}.tmp`;
      try {
        await writeFile(
          tmp,
          JSON.stringify({ version: 1, root, entries: parsed.entries }, null, 2),
          "utf8",
        );
        await rename(tmp, opts.cachePath);
      } catch (writeError) {
        await rm(tmp, { force: true }).catch(() => {});
        throw writeError;
      }
    } catch (error) {
      opts.warn(`dsh-mcp-manager: catalog cache remove failed: ${msgOf(error)}`);
    }
  }
}

/** 目录域唯一的内存目录实例：类不外放，外部 new 不出第二份目录。 */
export const catalogDirectory = new CatalogDirectory();

/** 目录新鲜判定：有条目、无 unavailable 段、且发现时间在 TTL 内
 *  （投影惰性重做专用；纯时间比较，无副作用）。 */
export function isCatalogFresh(catalog: CatalogServer | undefined): boolean {
  const {
    connection: { CATALOG_TTL_MS },
  } = catalogPorts.get();
  return (
    catalog !== undefined &&
    catalog.unavailable === undefined &&
    Date.now() - catalog.discoveredAt <= CATALOG_TTL_MS
  );
}

/** 单服务器目录装箱（投影专用纯函数）：按限额收敛工具清单——
 *  工具数上限 MAX_TOOLS_PER_SERVER、单描述字节上限 MAX_BYTES_PER_TOOL（超限
 *  截断）、累计字节上限 MAX_TOTAL_CATALOG_BYTES（超限即停）。行为与原
 *  discover 内联循环逐位一致（含 totalBytes 对截断后条目的计算口径）。 */
export function boundCatalogTools(
  tools: Iterable<{ name?: unknown; description?: unknown; inputSchema?: unknown }>,
): Map<string, CatalogTool> {
  const {
    connection: { MAX_TOOLS_PER_SERVER, MAX_BYTES_PER_TOOL, MAX_TOTAL_CATALOG_BYTES },
  } = catalogPorts.get();
  const bounded = new Map<string, CatalogTool>();
  let totalBytes = 0;
  for (const tool of tools) {
    if (bounded.size >= MAX_TOOLS_PER_SERVER) break;
    const name = String(tool.name ?? "");
    if (name === "") continue;
    const description = typeof tool.description === "string" ? tool.description : "";
    // B9：描述按 UTF-8 字节截断（slice 按字符会让中文等多字节场景超上限）；
    // 逐字符累加字节，保证截断点落在字符边界（不产生替换符）。
    let desc = description;
    if (Buffer.byteLength(desc, "utf8") > MAX_BYTES_PER_TOOL) {
      let bytes = 0;
      let cut = 0;
      while (
        cut < desc.length &&
        bytes + Buffer.byteLength(desc[cut], "utf8") <= MAX_BYTES_PER_TOOL
      ) {
        bytes += Buffer.byteLength(desc[cut], "utf8");
        cut += 1;
      }
      desc = desc.slice(0, cut);
    }
    bounded.set(name, {
      description: desc,
      inputSchema: (tool.inputSchema ?? {}) as Record<string, unknown>,
    });
    // B9：totalBytes 全字节口径（JSON.stringify().length 按码元计，低估字节数）
    totalBytes +=
      Buffer.byteLength(desc, "utf8") +
      Buffer.byteLength(JSON.stringify(bounded.get(name)?.inputSchema ?? {}), "utf8");
    if (totalBytes > MAX_TOTAL_CATALOG_BYTES) break;
  }
  return bounded;
}

/** 磁盘条目里的工具数组 → 内存工具表（非字符串名跳过；描述与 schema 缺省补空）。 */
function parsePersistedTools(raw: unknown): Map<string, CatalogTool> {
  const tools = new Map<string, CatalogTool>();
  if (!Array.isArray(raw)) return tools;
  for (const tool of raw) {
    const rec = tool as
      { name?: unknown; description?: unknown; inputSchema?: unknown } | undefined;
    if (typeof rec !== "object" || rec === null || typeof rec.name !== "string") continue;
    tools.set(rec.name, {
      description: typeof rec.description === "string" ? rec.description : "",
      inputSchema: (rec.inputSchema ?? {}) as Record<string, unknown>,
    });
  }
  return tools;
}

/** 封装定义 → 工具表（空名跳过；description 非字符串归空）。 */
function wrappedToolsOf(definitions: readonly unknown[]): Map<string, CatalogTool> {
  const tools = new Map<string, CatalogTool>();
  for (const definition of definitions) {
    const def = definition as { name?: unknown; description?: unknown; parameters?: unknown };
    if (typeof def?.name !== "string" || def.name === "") continue;
    tools.set(def.name, {
      description: typeof def.description === "string" ? def.description : "",
      inputSchema: (def.parameters ?? {}) as Record<string, unknown>,
    });
  }
  return tools;
}

/** 错误取消息：本域不 import pipeline 门面（会多一条跨域类型边），故只取 message 字段。 */
function msgOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/**
 * dsh-mcp-manager — catalog/impl/entries/index.ts：能力目录条目与渲染（#664 阶段 5）。
 *
 * 自 src/catalog.ts 拆出（目录条目域）：条目类型/摘要常量/摘要计算/条目组装/
 * 消息渲染与转义/消息定位读取。digest 与 history 归同域兄弟文件；目录注入决策
 * 归 injection.ts；注入端缓存视图归 cache-view.ts；检索族归 search.ts。
 */

import { randomUUID } from "node:crypto";
import type { SupervisorLite } from "../../../connection/interface.ts";
import type { CatalogMessage } from "../injection/index.ts";
import {
  DEFAULT_ANNOUNCE_CATALOG,
  DEFAULT_CATALOG_MAX_ENTRIES,
} from "../../../shared/interface.ts";

/** 目录条目。 */
export interface CatalogEntry {
  name: string;
  text?: string;
  /** 服务器归属（global/project）；用于区分调用引导（#228 双轨迁移）。 */
  scope?: string;
}

/** supervisor 最小面（manager.supervisors 的条目；物理定义在 connection/interface.ts，此处 re-export）。 */
export type { SupervisorLite } from "../../../connection/interface.ts";

/** 目录缓存（连接成功时持久化的工具描述摘要）。 */
export type CatalogCache = Map<string, { summary: string }>;

// ------------------------------------------------- 感知增强（对抗性评审 v2）

// 能力目录默认值的单一事实源已上移 server/shared/constants.ts：config/model 在模块求值期
// 消费它们，端口注入到时尚未装配；此处只保留转出，维持 catalog 门面与入口的导出面不变。
export { DEFAULT_ANNOUNCE_CATALOG, DEFAULT_CATALOG_MAX_ENTRIES };

/**
 * 能力目录消息的来源身份（#723）：`source.kind` 只能是宿主已登记的通用值
 * `plugin`，本插件的身份由 `source.plugin` 承载。
 *
 * 为什么不再自造 `kind`：宿主 v2→v3 迁移对 surface 消息的 `source.kind` 有一份
 * 封闭白名单（`dsh-session-format-v2-to-v3` 的 `SOURCE_KINDS`），自造值会让升级前
 * 落盘的会话永久无法迁移（原件保留、每次加载同样失败）。官方上下文包
 * （`dsh-time-context` / `dsh-tmux-context`）走的就是 `plugin` + 身份 + snapshot
 * 形态，这里与之一致：形态由宿主校验，身份由本包判定。
 */
export const CATALOG_SOURCE_PLUGIN = "@wingsky-1/dsh-mcp-manager";
/** 目录快照的段名（snapshot 形态下承载渲染后的目录正文）。 */
export const CATALOG_SECTION_NAME = "mcp-catalog";

/** 目录摘要总长上限（字符，含前缀与省略号）：目录注入 ≤6 条目，防远端工具描述
 * 堆叠稀释上下文；截断先于 escapeCatalogText 转义，防不可信输入注入超长文本。 */
export const CATALOG_SUMMARY_MAX_CHARS = 240;
/** 目录摘要单句上限（字符）：无句读语言 / 超长描述的安全截断点。 */
export const CATALOG_SUMMARY_PER_TOOL_CHARS = 120;
/** 目录单条服务器描述上限（字符）：Level 1 发现层防远端超长说明书（如 context7 500 词）
 * 撑爆会话上下文，符合渐进式披露原则。详细使用说明由 ws_mcp_detail / ws_mcp_search 按需承载。 */
export const CATALOG_ENTRY_MAX_CHARS = 180;

/**
 * 从工具描述集合计算目录摘要（每工具取首句，按工具名升序 + 精确去重后拼接）。
 *
 * 为什么不再「排序取第一条」（#569）：tavily 等服务器的字典序第一条是次要工具
 * （tavily_crawl），会把搜索服务器描述成爬虫、误导模型。改为每工具贡献首句：
 * - 排序（按工具名而非描述）保证工具列表顺序/描述空白抖动时摘要稳定（重连不触发
 *   缓存更新 → digest 不变）；
 * - 首句提取（firstSentenceOf）防 "1." 编号 / URL / 缩写误切；多字节按字符截断；
 * - 总长与单句均有上限：目录摘要的用途是让模型判断「该不该调这个服务器」，过长
 *   描述（含远端不可信输入）反而稀释上下文；完整能力清单由 ws_mcp_list /
 *   工具注册表承担，不塞进目录。
 */
export function summarizeToolDescriptions(
  toolMeta: Map<string, { description?: unknown }>,
): string | undefined {
  // ① 收集 (工具名, 首句)（非空）；全空 → undefined。
  const collected: Array<[string, string]> = [];
  for (const [name, meta] of toolMeta) {
    const sentence = firstSentenceOf(meta?.description);
    if (sentence === "") continue;
    collected.push([name, sentence]);
  }
  if (collected.length === 0) return undefined;
  // ② 按工具名升序（确定性：顺序抖动只变内容不变名序）→ 精确去重。
  collected.sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
  const seen = new Set<string>();
  const sentences: string[] = [];
  for (const [, sentence] of collected) {
    if (seen.has(sentence)) continue;
    seen.add(sentence);
    sentences.push(
      sentence.length <= CATALOG_SUMMARY_PER_TOOL_CHARS
        ? sentence
        : `${charTruncate(sentence, CATALOG_SUMMARY_PER_TOOL_CHARS - 1)}…`,
    );
  }
  const prefix = collected.length >= 2 ? `${collected.length} tools: ` : "";
  // ③ 拼接（"; " 分隔），超总长按句整段回退补 "…"（绝不句中切）。
  let text = prefix;
  for (const sentence of sentences) {
    const separator = text === prefix ? "" : "; ";
    if (text.length + separator.length + sentence.length <= CATALOG_SUMMARY_MAX_CHARS - 1) {
      text += separator + sentence;
    } else if (text === prefix) {
      // 前缀后连一句都放不下（极端长句）→ 前缀 + 截断 + 省略号。
      return `${prefix}${charTruncate(sentence, CATALOG_SUMMARY_MAX_CHARS - prefix.length - 1)}…`;
    } else {
      // 已容纳若干句 → 保留完整句，尾部补省略号表示还有更多工具。
      return `${text}…`;
    }
  }
  return text;
}

/** 判定 text[index] 处是否为句界：回答「这里断句吗？」——前置数字（编号/版本/
 * 小数）不算句读；句读后须空白 + 大写字母/汉字才算新句（防 URL / e.g. 缩写误切）。
 * 逐字扫描的驱动在 firstSentenceOf 内（不同问题）。
 * @returns `false` 非句界（继续扫描）；`"end"` 句读收尾（整行即句）；`"mid"` 句中
 *   句界（切至此处含标点）。 */
function sentenceBoundaryKind(text: string, index: number): "end" | "mid" | false {
  if (index > 0 && text[index - 1] >= "0" && text[index - 1] <= "9") return false;
  let next = index + 1;
  while (next < text.length && /\s/u.test(text[next])) next += 1;
  if (next >= text.length) return "end"; // 句读收尾（"…URL."）→ 整行即句，不剥标点
  if (/[A-Za-z\u4e00-\u9fff]/u.test(text[next] as string)) return "mid"; // 句读后随大写/汉字 → 新句
  return false;
}

/** 取描述首行的首个完整句（MCP 描述惯例：首行即概要；多行 docstring 的参数
 * 说明留给工具详情/ws_mcp_detail，不进目录摘要）。
 * 句界判定防误切："1." 编号/版本/小数（句读前置数字）、URL / e.g. 缩写（句读后
 * 须空白 + 大写字母/汉字才算新句）；无句读 → 整行返回。
 * @returns 首句；空输入 → ""。 */
function firstSentenceOf(description: unknown): string {
  const raw = typeof description === "string" ? description : "";
  if (raw.trim() === "") return "";
  const firstLine = raw.split(/\r?\n/u)[0] ?? "";
  const text = firstLine.replace(/\s+/gu, " ").trim();
  if (text === "") return "";
  for (let index = 0; index < text.length; index += 1) {
    const ch = text[index];
    if (ch !== "." && ch !== "!" && ch !== "?" && ch !== "。" && ch !== "！" && ch !== "？")
      continue;
    const kind = sentenceBoundaryKind(text, index);
    if (kind === false) continue;
    if (kind === "end") return text; // 句读收尾（"…URL."）→ 整行即句，不剥标点
    return text.slice(0, index + 1);
  }
  return text;
}

/** 按 Unicode 字符截断（防切代理对/emoji；JS length 为 UTF-16 码元）。 */
function charTruncate(text: string, maxChars: number): string {
  if (maxChars <= 0) return "";
  return [...text].slice(0, maxChars).join("");
}

// --------------------------------------------- L1 能力目录（感知增强）

/**
 * 生成能力目录条目（**数据源不依赖用户配置、不依赖实时连接状态**）：
 * ① 服务器自定义 description（用户可选补充，优先）→
 * ② 目录缓存摘要（连接成功时自动持久化的工具描述摘要，磁盘数据，与连接状态解耦）
 * ③ 都没有 → 只显示服务器名。
 * 连接/断开/重连不改变缓存内容 → digest 稳定 → 不触发重复注入。
 * @param supervisors manager.supervisors（name → supervisor）。
 * @param maxEntries 最大条目数。
 * @param cache 目录缓存（manager.catalogCache）。
 * @returns 目录条目。
 */
export function composeCatalogEntries(
  supervisors: Map<string, SupervisorLite>,
  maxEntries = DEFAULT_CATALOG_MAX_ENTRIES,
  cache?: CatalogCache,
): CatalogEntry[] {
  const entries: CatalogEntry[] = [];
  for (const [name, supervisor] of supervisors) {
    if (entries.length >= maxEntries) break;
    const server = supervisor.server;
    let text;
    if (typeof server.description === "string" && server.description !== "") {
      const sentence = firstSentenceOf(server.description);
      const raw = sentence !== "" ? sentence : server.description.trim().replace(/\s+/gu, " ");
      text =
        raw.length <= CATALOG_ENTRY_MAX_CHARS
          ? raw
          : `${charTruncate(raw, CATALOG_ENTRY_MAX_CHARS - 1)}…`;
    } else {
      const cached = cache?.get(name);
      if (typeof cached?.summary === "string" && cached.summary !== "") text = cached.summary;
    }
    // 无描述时剥离 text 属性（不产出 `text: undefined`）：条目保持干净可
    // JSON 序列化，否则目录消息 append 为 user/message 事件会被 dsh-session
    // 序列化校验拒绝（issue #192）。
    const scope = typeof supervisor.scope === "string" ? supervisor.scope : undefined;
    const entry: CatalogEntry = { name };
    if (text !== undefined) entry.text = text;
    if (scope !== undefined) entry.scope = scope;
    entries.push(entry);
  }
  return entries;
}

/** 渲染能力目录消息（source 标记供定位替换）。
 *
 * 按条目 scope 只区分「是否附项目级更严格的那条引导」（#228 双轨迁移；#767 S1-5b 收敛为
 * id 口径）：#767 笔 2 起 `mcp__*` 已不在模型可见面（笔 1b 的可见面收敛），**全部**服务器
 * ——项目级、全局级、封装定义条目（toolDefinitions）——一律经中间层工具访问。原来按 `mode`
 * 分出的「全局一律直呼 `mcp__<id>__<tool>`」分支是笔 1b 之后已假的事实，随 `mode` 一并删除；
 * 兜底引导同理（写成直呼会让模型在无 `mcp__` 可见面时无路可走）。
 */
export function renderMcpCatalogMessage(entries: CatalogEntry[]): CatalogMessage {
  const hasProject = entries.some((entry) => entry.scope === "project");
  const projectGuidance =
    "Project-level servers MUST be accessed via middleware tools: search with `ws_mcp_search`, verify schema with `ws_mcp_detail` if uncertain, then invoke with `ws_mcp_call` (use `ws_mcp_list` for full inventory audits). **Do NOT invoke project-level servers using mcp__ prefixed tools directly**.";
  const globalGuidance =
    "Global servers are also accessed via middleware: search with `ws_mcp_search`, then invoke with `ws_mcp_call` using the same `ws_mcp_*` suite (address them by full name `@global/<server>`).";
  const guidance = hasProject ? `${projectGuidance} ${globalGuidance}` : globalGuidance;
  const lines = [
    "<system-reminder>",
    'Configured MCP servers in this session (**capability descriptions only, does not reflect active connection status**; tools register once connected via GUI "MCP" popup):',
    "",
    "<available_mcp_servers>",
    // 服务器名与描述同为远端可控输入：同口径转义后才可拼入目录正文，避免标签逃逸改写注入语义；摘要仍以原始名计算，转义不改变去重口径。
    ...entries.map((entry) =>
      entry.text === undefined
        ? `- \`${escapeCatalogText(entry.name)}\``
        : `- \`${escapeCatalogText(entry.name)}\`: ${escapeCatalogText(entry.text)}`,
    ),
    "</available_mcp_servers>",
    "",
    guidance,
    'If a server was available but is now disconnected, do not retry the same tool more than twice. Switch to an alternative method or ask the user to check the "MCP" popup.',
    "</system-reminder>",
  ].join("\n");
  return {
    id: randomUUID(),
    role: "user",
    content: [{ type: "text", text: lines }],
    source: {
      kind: "plugin",
      plugin: CATALOG_SOURCE_PLUGIN,
      form: "snapshot",
      sections: [{ name: CATALOG_SECTION_NAME, text: lines }],
    },
  };
}

/** 转义远程来源文本（防提示注入/标签逃逸；与 skill catalog 的 escapeText 同思路）。
 * 只做安全转义，**不做长度截断**（完整返回描述）。 */
export function escapeCatalogText(value: unknown): string {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replace(/[\r\n]/gu, " ");
}

/** 是否为本插件注入的能力目录消息（新旧两代 source 形态都认，#723 跨版本兼容）。 */
export function isCatalogSource(source: { kind?: unknown; plugin?: unknown } | undefined): boolean {
  if (source === undefined) return false;
  if (source.kind === "mcp-catalog") return true;
  return source.kind === "plugin" && source.plugin === CATALOG_SOURCE_PLUGIN;
}

/** 从消息列表里定位既有的能力目录消息（新旧两代 source 形态都认）。 */
export function findCatalogMessage(messages: CatalogMessage[]): CatalogMessage | undefined {
  for (const message of messages) {
    if (isCatalogSource(message?.source)) return message;
  }
  return undefined;
}

/**
 * 取回一条目录消息所发布的条目。
 *
 * 新旧两代形态（#723）：
 * - 旧形态 `{ kind: "mcp-catalog", form: "catalog", entries }`：逐条还原条目，
 *   digest 与升级前完全一致；
 * - 新形态 `{ kind: "plugin", form: "snapshot", sections: [{ name, text }] }`：
 *   从快照正文的 `<available_mcp_servers>` 块还原条目（格式化是单射的），使
 *   digest 与 `composeCatalogEntries` 的条目 digest 同口径——否则每次启动都会
 *   误判"目录已变"而注入一条修正帧。
 *
 * 坏数据返回 undefined（按"不是本插件的目录"处理）：本函数在 step 监听器里被调用，
 * 抛错会让该会话每一轮都失败。
 */
export function resolveCatalogEntries(
  source: CatalogSourceLike | undefined,
): CatalogEntry[] | undefined {
  if (!isCatalogSource(source)) return undefined;
  if (source?.kind === "plugin") {
    const sections = source.sections;
    if (!Array.isArray(sections)) return undefined;
    const section = sections.find(
      (candidate) =>
        typeof candidate === "object" &&
        candidate !== null &&
        (candidate as { name?: unknown }).name === CATALOG_SECTION_NAME &&
        typeof (candidate as { text?: unknown }).text === "string",
    ) as { text: string } | undefined;
    if (section === undefined) return undefined;
    return parseCatalogBody(section.text);
  }
  const entries = source?.entries;
  if (!Array.isArray(entries)) return undefined;
  const readable: CatalogEntry[] = [];
  for (const entry of entries) {
    if (typeof entry !== "object" || entry === null) return undefined;
    const { name, text } = entry as { name?: unknown; text?: unknown };
    if (typeof name !== "string" || name === "") return undefined;
    readable.push({ name, text: typeof text === "string" ? text : undefined });
  }
  return readable;
}

/** 还原渲染时的反转义（escapeCatalogText 的逆；`&amp;` 最后解，避免二次解码）。 */
function unescapeCatalogText(text: string): string {
  return text.replaceAll("&lt;", "<").replaceAll("&gt;", ">").replaceAll("&amp;", "&");
}

/**
 * 从目录快照正文解析条目：格式化是单射的（`- \`name\`` 或 `- \`name\`: text`），
 * 解析失败按"不是本插件的目录"返回 undefined。
 */
function parseCatalogBody(body: string): CatalogEntry[] | undefined {
  const lines = body.split("\n");
  const start = lines.indexOf("<available_mcp_servers>");
  if (start < 0) return undefined;
  const end = lines.indexOf("</available_mcp_servers>", start + 1);
  if (end < 0) return undefined;
  const entries: CatalogEntry[] = [];
  for (const line of lines.slice(start + 1, end)) {
    const match = /^- `([^`]+)`(?:: (.*))?$/u.exec(line);
    if (match === null) return undefined;
    // 与渲染侧对称：目录正文中的转义名还原为原始名，保证回读条目与组装条目一致，注入比对不误判。
    entries.push(
      match[2] === undefined
        ? { name: unescapeCatalogText(match[1]) }
        : { name: unescapeCatalogText(match[1]), text: unescapeCatalogText(match[2]) },
    );
  }
  return entries;
}

/**
 * 防御性读取目录 source 里的条目（坏数据返回 undefined）。
 *
 * 保留旧签名与旧语义（只读已发布形态的 `entries`）：它是包导出面与既有单测的契约，
 * 新形态的读取走 {@link resolveCatalogEntries}。
 */
export function readCatalogEntries(
  source: { entries?: unknown } | undefined,
): CatalogEntry[] | undefined {
  const entries = source?.entries;
  if (!Array.isArray(entries)) return undefined;
  const readable: CatalogEntry[] = [];
  for (const entry of entries) {
    if (typeof entry !== "object" || entry === null) return undefined;
    const { name, text } = entry;
    if (typeof name !== "string" || name === "") return undefined;
    readable.push({ name, text: typeof text === "string" ? text : undefined });
  }
  return readable;
}

/** 目录 source 最小面（新旧两代形态；判定见 {@link isCatalogSource}）。 */
export interface CatalogSourceLike {
  kind?: unknown;
  plugin?: unknown;
  entries?: unknown;
  sections?: unknown;
}

/** 渲染"目录更新"消息（历史旧目录无法删除，新消息声明作废——与 tool-skill 同语义）。 */
export function renderMcpCatalogUpdate(entries: CatalogEntry[]): CatalogMessage {
  const body = renderMcpCatalogMessage(entries);
  const inner = body.content![0].text!.split("\n").slice(3).join("\n");
  const text = [
    "<system-reminder>",
    "MCP server configuration has changed. **This catalog replaces all previous available_mcp_servers lists**:",
    "",
    inner,
    "</system-reminder>",
  ].join("\n");
  return { ...body, content: [{ type: "text", text }] };
}

/**
 * dsh-mcp-manager — catalog/impl/history/index.ts：会话内目录历史定位（#664 阶段 5）。
 *
 * 自 src/catalog.ts 拆出（history 域）：从会话持久化日志倒序找最后一条**可见**
 * 的能力目录消息——目录注入去重的权威来源。新旧两代 source 形态都认（#723）。
 */

import { digestCatalogEntries } from "../digest/index.ts";
import { isCatalogSource, resolveCatalogEntries } from "../entries/index.ts";
import type { CatalogSourceLike } from "../entries/index.ts";

/** 目录历史查询结果。 */
export interface CatalogHistoryResult {
  visibleDigest?: string;
  published: boolean;
}

/** agent 最小面（session.snapshotEvents() 倒序找目录消息；0.1.2-rc.1 起 events getter 移除）。 */
export interface CatalogAgent {
  session?: {
    surface?: { nodes?: unknown[] };
    snapshotEvents?: () => ReadonlyArray<{
      type?: string;
      seq?: unknown;
      data?: { source?: CatalogSourceLike };
    }>;
  };
}

/** 判定单条会话事件是否为可定位的目录消息：回答「这条事件带目录吗？」——
 * 类型 + 来源身份 + 条目解析三关，任一不符即非目录事件（调用方继续倒序）。
 * 可见性判定（surface.nodes）留在 catalogHistory 内（不同问题）。
 * @returns 可定位时返回目录条目；否则 undefined。 */
function matchCatalogEvent(
  event: { type?: string; data?: { source?: CatalogSourceLike } } | undefined,
): ReturnType<typeof resolveCatalogEntries> {
  if (event?.type !== "user/message") return undefined;
  if (!isCatalogSource(event.data?.source)) return undefined;
  return resolveCatalogEntries(event.data?.source);
}

/**
 * 从会话持久化日志（agent.session.snapshotEvents()）倒序找最后一条**可见**的
 * 能力目录消息。**这是去重的权威来源**（与官方 dsh-tool-skill catalogHistory
 * 同构）：
 * - decision.messages 只含本轮新消息，历史目录消息不在其中——用它定位会导致每轮重复注入；
 * - 可见性（surface.nodes）过滤：compaction/resume 后旧目录不可见 → visibleDigest 为空 → 重新注入；
 * - 新旧两代 source 形态共存（#723 升级前的会话仍是 mcp-catalog + entries）。
 */
export function catalogHistory(agent: CatalogAgent | undefined): CatalogHistoryResult {
  const visible = new Set(agent?.session?.surface?.nodes ?? []);
  const events = agent?.session?.snapshotEvents?.() ?? [];
  let published = false;
  for (let index = events.length - 1; index >= 0; index -= 1) {
    const event = events[index];
    const entries = matchCatalogEvent(event);
    if (entries === undefined) continue;
    published = true;
    if (visible.has(event?.seq)) return { visibleDigest: digestCatalogEntries(entries), published };
  }
  return { published };
}

/**
 * dsh-mcp-manager — catalog/impl/injection/index.ts：能力目录注入决策（#664 阶段 5）。
 *
 * 自 src/catalog.ts 拆出（injection 域）：pre-step 监听器的目录注入决策纯函数，
 * 完全复刻官方 dsh-tool-skill 的 catalog 语义（根治重复注入）。
 */

import {
  composeCatalogEntries,
  findCatalogMessage,
  resolveCatalogEntries,
  renderMcpCatalogMessage,
  renderMcpCatalogUpdate,
  DEFAULT_CATALOG_MAX_ENTRIES,
} from "../entries/index.ts";
import type { CatalogCache, SupervisorLite } from "../entries/index.ts";
import { digestCatalogEntries } from "../digest/index.ts";
import { catalogHistory } from "../history/index.ts";
import type { CatalogAgent } from "../history/index.ts";

/** 会话消息最小面（pre-step decision.messages / session.snapshotEvents()）。 */
export interface CatalogMessage {
  id?: unknown;
  role?: string;
  content?: Array<{ type?: string; text?: string }>;
  source?: {
    kind?: unknown;
    plugin?: unknown;
    form?: unknown;
    entries?: unknown;
    sections?: unknown;
  };
}

/** pre-step 决策最小面。 */
export interface CatalogDecision {
  kind: string;
  messages: CatalogMessage[];
}

/**
 * 目录注入决策（纯函数，pre-step 监听器薄调用，便于单测）。
 * 完全复刻官方 dsh-tool-skill 的 catalog 语义（根治重复注入）：
 * 1. 历史（session.snapshotEvents()）digest 相同 → 本轮不注入（撤销本轮已注入的）——**去重源是历史而非本轮消息**；
 * 2. 历史 digest 不同 → 注入"更新"消息（声明替换旧目录）；
 * 3. 从未发布且无服务器 → 不注入；
 * 4. compaction/resume 后旧目录不可见 → 重新注入（events-based 重建）。
 * @param decision next() 的决策。
 * @param messages 本轮输入消息（签名兼容）。
 * @param supervisors manager.supervisors。
 * @param maxEntries 目录条目上限。
 * @param cache 目录缓存。
 * @param agent pre-step 的 agent（session.snapshotEvents() 来源）。
 * @returns 新决策。
 */
export function resolveCatalogInjection(
  decision: CatalogDecision,
  messages: CatalogMessage[],
  supervisors: Map<string, SupervisorLite>,
  maxEntries = DEFAULT_CATALOG_MAX_ENTRIES,
  cache?: CatalogCache,
  agent?: CatalogAgent,
): CatalogDecision {
  if (decision.kind === "reject") return decision;
  const entries = composeCatalogEntries(supervisors, maxEntries, cache);
  const digest = digestCatalogEntries(entries);
  const history = catalogHistory(agent);
  const existing = findCatalogMessage(decision.messages);

  if (history.visibleDigest === digest) {
    // 历史已发布相同目录 → 本轮不注入；撤销本轮刚注入的（幂等）。
    return existing === undefined
      ? decision
      : {
          kind: "enter",
          messages: decision.messages.filter((message) => message.id !== existing.id),
        };
  }
  if (existing !== undefined) {
    const existingEntries = resolveCatalogEntries(existing.source);
    if (existingEntries !== undefined && digestCatalogEntries(existingEntries) === digest)
      return decision;
  }
  if (!history.published && entries.length === 0) {
    return existing === undefined
      ? decision
      : {
          kind: "enter",
          messages: decision.messages.filter((message) => message.id !== existing.id),
        };
  }
  const catalog = history.published
    ? renderMcpCatalogUpdate(entries)
    : renderMcpCatalogMessage(entries);
  return {
    kind: "enter",
    messages:
      existing === undefined
        ? [...decision.messages, catalog]
        : decision.messages.map((message) => (message.id === existing.id ? catalog : message)),
  };
}

/**
 * dsh-mcp-manager — catalog/impl/service/index.ts：目录域端口持有者（#767 B2a-wire W4）。
 *
 * 域内实现经 `catalogPorts.get()` 取数，写入只发生在组合根入口顶层的 `installCatalog`
 * （见 `src/index.ts`）。形态照 `server/upgrade/impl/service/` 的 runner：模块级只有一个
 * `const` 实例、状态收进实例字段（I9），装配与复位只经方法（方法内赋值）。
 */
import type { CatalogDeps } from "../../deps.ts";

/** 目录域端口表：装配一次、域内多处读。 */
class CatalogPorts {
  /** 未装配时保持 undefined——「没装配」与「装配了空实现」必须可区分（I6）。 */
  private deps: CatalogDeps | undefined;

  /** 装配：组合根递入静态模块引用；重复装配是编程错误，当场暴露。 */
  install(deps: CatalogDeps): void {
    if (this.deps !== undefined) throw new Error("dsh-mcp-manager: catalog 域只能装配一次");
    this.deps = deps;
  }

  /** 卸载：只复位装配标记，本域没有别的活资源要释放。 */
  release(): void {
    this.deps = undefined;
  }

  /**
   * 域内取数的唯一入口。未装配即抛错而不是回落默认值：默认值会让「组合根漏装」表现成
   * 行为正常但参数不对（目录 TTL 与检索/装箱限额静默换值），症状与本插件毫无字面关联。
   */
  get(): CatalogDeps {
    const deps = this.deps;
    if (deps === undefined) {
      throw new Error(
        "dsh-mcp-manager: catalog 域未装配——组合根未在入口调用 installCatalog（src/index.ts）",
      );
    }
    return deps;
  }
}

/** 本域唯一的装配实例：类不外放，外部 new 不出第二份端口表。 */
export const catalogPorts = new CatalogPorts();

/**
 * dsh-mcp-manager — catalog/search.ts：能力目录检索函数族（#664 阶段 5）。
 *
 * 自 src/middleware-utils.ts 迁出（catalog 域检索族）：打分/单/多单元检索/
 * 完整盘点/单工具详情/新鲜判定/装箱。工具级禁用裁决（isToolDenied 等）与
 * globMatch 归 pipeline（authorize 块）。B10 截断事实
 * 口径随迁保持「恰好命中 limit 不误报」。
 */

import { MIDDLEWARE_GLOBAL_ROOT } from "../../shared/interface.ts";
import { LIST_DEFAULT_TOOLS_PER_SERVER } from "../shared/interface.ts";
import { catalogDirectory } from "./impl/directory/index.ts";
import { catalogPorts } from "./impl/service/index.ts";
import type {
  CatalogTool,
  ListCatalogResult,
  ListServerEntry,
  ListToolEntry,
  SearchHit,
  ToolDetail,
} from "./interface.ts";
import type { ProjectUnit } from "../connection/interface.ts";
import type { DisabledToolsMap } from "../store/interface.ts";

/** 简单分词（英文小写 + 中文保留）。 */
function tokenize(text: string): string[] {
  const lowered = text.toLowerCase();
  const words = lowered.match(/[a-z0-9_]+|[\u4e00-\u9fff]+/gu) ?? [];
  return words;
}

/** 跨字段打分：query 词命中 server 名 / 工具名 / description / 参数名。
 * 中文（无空格分词）：query 连续中文串在原始描述中 substring 匹配即可命中
 * （修复：原实现把连续中文当单个 token，中文召回率接近零）。 */
export function scoreTool(
  query: string,
  server: string,
  toolName: string,
  tool: CatalogTool,
): { score: number; matchedTerms: string[] } {
  if (query === "") return { score: 0, matchedTerms: [] };
  const haystack = [
    server,
    toolName,
    tool.description,
    JSON.stringify(Object.keys(tool.inputSchema ?? {})),
  ]
    .join(" ")
    .toLowerCase();
  // 中文子串匹配（连续中文段直接 substring 命中原始文本）
  const cjkQuery = query.match(/[\u4e00-\u9fff]+/gu) ?? [];
  if (cjkQuery.length > 0) {
    let score = 0;
    const matchedTerms: string[] = [];
    for (const segment of cjkQuery) {
      if (segment.length < 2) continue;
      if (haystack.includes(segment)) {
        score += 2;
        matchedTerms.push(segment);
      }
    }
    if (score > 0) return { score, matchedTerms };
  }
  const terms = tokenize(query);
  if (terms.length === 0) return { score: 0, matchedTerms: [] };
  let score = 0;
  const matchedTerms: string[] = [];
  for (const term of terms) {
    if (term.length < 2) continue;
    if (haystack.includes(term)) {
      score += 1;
      matchedTerms.push(term);
    }
  }
  return { score, matchedTerms };
}

/** 检索目录：query 为空 → 能力摘要表（每服务器前 N 个工具）。
 * 单 root 实现（searchCatalogMulti 循环调用；兼容既有测试）。
 * truncated：任一服务器存在被 limit 裁掉的结果即 true（B10 截断事实，
 * 供调用方精确标注「是否因 limit 裁掉」——恰好命中 limit 不误报）。 */
export function searchCatalog(
  units: Map<string, ProjectUnit>,
  root: string,
  query: string,
  limit: number,
): {
  results: SearchHit[];
  unavailable: Array<{ server: string; reason: string }>;
  truncated: boolean;
} {
  const {
    connection: { CATALOG_TTL_MS },
    workspace: { fullServerName },
  } = catalogPorts.get();
  if (!units.has(root)) return { results: [], unavailable: [], truncated: false };
  const servers = catalogDirectory.serversFor(root);
  if (servers === undefined) return { results: [], unavailable: [], truncated: false };
  const results: SearchHit[] = [];
  const unavailable: Array<{ server: string; reason: string }> = [];
  let truncated = false;
  for (const [serverName, catalog] of servers) {
    if (catalog.unavailable !== undefined) {
      unavailable.push({ server: fullServerName(root, serverName), reason: catalog.unavailable });
      continue;
    }
    const fresh = Date.now() - catalog.discoveredAt <= CATALOG_TTL_MS;
    const scored: Array<{
      server: string;
      toolName: string;
      tool: CatalogTool;
      score: number;
      matchedTerms: string[];
    }> = [];
    for (const [toolName, tool] of catalog.tools) {
      const { score, matchedTerms } = scoreTool(query, serverName, toolName, tool);
      if (query !== "" && score === 0) continue;
      scored.push({ server: serverName, toolName, tool, score, matchedTerms });
    }
    scored.sort((a, b) => b.score - a.score || a.toolName.localeCompare(b.toolName));
    if (scored.length > limit) truncated = true;
    for (const hit of scored.slice(0, limit)) {
      results.push({
        server: fullServerName(root, hit.server),
        tool: hit.toolName,
        description: hit.tool.description,
        inputSchema: hit.tool.inputSchema,
        score: hit.score,
        matchedTerms: hit.matchedTerms,
        fresh,
      });
    }
  }
  return { results, unavailable, truncated };
}

/** 多单元合并检索（项目 root 单元 + @global 单元合并查询）。
 * 与 searchCatalog 同语义，仅数据源扩展为多个 root。
 * 单 root 直接委托 searchCatalog（保持原顺序，不引入跨单元排序变化）；
 * 多 root 合并后统一排序并按全局 limit 截断（truncated=合并后曾有超限结果）。 */
export function searchCatalogMulti(
  units: Map<string, ProjectUnit>,
  roots: readonly string[],
  query: string,
  limit: number,
): {
  results: SearchHit[];
  unavailable: Array<{ server: string; reason: string }>;
  truncated: boolean;
} {
  if (roots.length === 1) {
    return searchCatalog(units, roots[0] as string, query, limit);
  }
  const results: SearchHit[] = [];
  const unavailable: Array<{ server: string; reason: string }> = [];
  for (const root of roots) {
    const single = searchCatalog(units, root, query, limit);
    results.push(...single.results);
    unavailable.push(...single.unavailable);
  }
  // 跨单元排序（评分降序，工具名升序）——与单单元检索同序。
  results.sort((a, b) => b.score - a.score || a.tool.localeCompare(b.tool));
  // 合并后统一截断（limit 为全局上限，而非每 root 上限）；截断事实供调用方标注。
  const truncated = results.length > limit;
  return { results: results.slice(0, limit), unavailable, truncated };
}

/** 构建单服务器工具条目（含禁用标注与截断）：回答「这台服务器列出哪些工具？」——
 * 逐工具裁禁用（本 root 段 + @global 段并集命中即标注）+ perServerLimit 截断；
 * 盘点范围解析与跨单元排序在 listCatalog 内（不同问题）。
 *
 * 条件赋值而非 `disabled: x || undefined`——显式 undefined 键会被宿主
 * lossless JSON 输出校验（dsh-util-values walkJsonValue）判非法
 * （#381：ws_mcp_list 报 "value is not lossless JSON"）。
 */
function buildListToolEntries(
  tools: Map<string, CatalogTool>,
  safeLimit: number,
  disabledTools: DisabledToolsMap | undefined,
  root: string,
  serverName: string,
): { entries: ListToolEntry[]; truncated: boolean } {
  const entries: ListToolEntry[] = [];
  let truncated = false;
  let index = 0;
  for (const [toolName, tool] of tools) {
    if (index >= safeLimit) {
      truncated = true;
      break;
    }
    // 工具级禁用标注（与服务器级 disabled 并列；查询面供模型感知）。
    const rootTools = disabledTools?.get(root)?.get(serverName);
    const globalTools =
      root === MIDDLEWARE_GLOBAL_ROOT
        ? undefined
        : disabledTools?.get(MIDDLEWARE_GLOBAL_ROOT)?.get(serverName);
    const disabledByUser =
      (rootTools !== undefined && rootTools.has(toolName)) ||
      (globalTools !== undefined && globalTools.has(toolName));
    const toolEntry: ListToolEntry = { tool: toolName, description: tool.description };
    if (disabledByUser) toolEntry.disabled = true;
    entries.push(toolEntry);
    index += 1;
  }
  return { entries, truncated };
}

/** 解析盘点范围：回答「哪些 root 参与盘点？」——@全名过滤定 root，root 越界抛
 * 路由一致性错误（与 ws_mcp_call 口径一致）；无过滤时全 root 参与。
 * 工具条目构建与排序在 listCatalog 内（不同问题）。 */
function resolveListRoots(
  roots: readonly string[],
  serverFilter: string | undefined,
): Set<string> | undefined {
  if (serverFilter !== undefined && serverFilter.startsWith("@")) {
    const {
      workspace: { parseFullServerName },
    } = catalogPorts.get();
    const parsed = parseFullServerName(serverFilter);
    if (parsed === undefined || !roots.includes(parsed.root)) {
      throw new Error(
        `ws_mcp_list: server ${JSON.stringify(serverFilter)} 不属于当前工作空间（${JSON.stringify(roots)}）；路由一致性校验失败（防跨空间串台）`,
      );
    }
    return new Set([parsed.root]);
  }
  return undefined;
}

/**
 * 完整盘点：列出当前工作空间全部服务器 + 每台完整工具清单（不受关键词/limit
 * 截断服务器，工具数受 perServerLimit 保护）。
 * @param units 连接池单元集合。
 * @param roots 参与盘点的 root 列表（当前项目 root + @global）。
 * @param serverFilter 可选：@<root>/<server> 全名或裸名过滤。
 * @param toolLimit 每服务器工具条数上限（>0；超过置 toolsTruncated）。
 * @param emptyHint 空返回时的 message。
 * @param disabledTools 用户工具级禁用映射（root → server → Set<tool>）；
 *    命中条目在工具行标注禁用（供模型感知）。
 * @throws 全名 root 不属于当前 roots → 路由一致性错误（与 ws_mcp_call 口径一致）。
 */
export function listCatalog(
  units: Map<string, ProjectUnit>,
  roots: readonly string[],
  serverFilter: string | undefined,
  toolLimit: number,
  emptyHint: string,
  disabledTools?: DisabledToolsMap,
): ListCatalogResult {
  const {
    workspace: { fullServerName },
  } = catalogPorts.get();
  const safeLimit =
    Number.isFinite(toolLimit) && toolLimit > 0
      ? Math.floor(toolLimit)
      : LIST_DEFAULT_TOOLS_PER_SERVER;
  const rootSet = resolveListRoots(roots, serverFilter);
  const servers: ListServerEntry[] = [];
  let totalTools = 0;
  let anyTruncated = false;
  for (const root of roots) {
    if (rootSet !== undefined && !rootSet.has(root)) continue;
    const unit = units.get(root);
    if (unit === undefined) continue;
    const rootCatalog = catalogDirectory.serversFor(root);
    if (rootCatalog === undefined) continue;
    for (const [serverName, catalog] of rootCatalog) {
      if (
        serverFilter !== undefined &&
        serverName !== serverFilter &&
        fullServerName(root, serverName) !== serverFilter
      )
        continue;
      const entry: ListServerEntry = {
        server: fullServerName(root, serverName),
        tools: [],
        toolsTruncated: false,
      };
      if (unit.userDisabled.has(serverName)) entry.disabled = true;
      if (catalog.unavailable !== undefined) {
        entry.unavailable = catalog.unavailable;
      } else {
        const built = buildListToolEntries(
          catalog.tools,
          safeLimit,
          disabledTools,
          root,
          serverName,
        );
        entry.tools = built.entries;
        entry.toolsTruncated = built.truncated;
        if (built.truncated) anyTruncated = true;
        totalTools += built.entries.length;
      }
      servers.push(entry);
    }
  }
  return finalizeListResult(servers, roots, totalTools, anyTruncated, emptyHint);
}

/** 定序组装盘点结果：回答「结果按什么顺序摆？」——稳定排序（root 出现序 +
 * 服务器名，跨单元合并不依赖 Map 插入序）+ 空结果提示；范围与条目构建在
 * listCatalog 内（不同问题）。 */
function finalizeListResult(
  servers: ListServerEntry[],
  roots: readonly string[],
  totalTools: number,
  anyTruncated: boolean,
  emptyHint: string,
): ListCatalogResult {
  const {
    workspace: { parseFullServerName },
  } = catalogPorts.get();
  const rootIndex = new Map(roots.map((root, index) => [root, index]));
  servers.sort((a, b) => {
    const ra = parseFullServerName(a.server)?.root ?? "";
    const rb = parseFullServerName(b.server)?.root ?? "";
    const oa = rootIndex.get(ra) ?? Number.MAX_SAFE_INTEGER;
    const ob = rootIndex.get(rb) ?? Number.MAX_SAFE_INTEGER;
    if (oa !== ob) return oa - ob;
    const sa = parseFullServerName(a.server)?.server ?? a.server;
    const sb = parseFullServerName(b.server)?.server ?? b.server;
    return sa.localeCompare(sb);
  });
  const result: ListCatalogResult = {
    workspace: roots[0] ?? "@global",
    servers,
    totalServers: servers.length,
    totalTools,
    toolsTruncated: anyTruncated,
  };
  if (servers.length === 0) result.message = emptyHint;
  return result;
}

/**
 * 单工具详情：按 @<root>/<server> + tool 裸名精确命中，返回完整 inputSchema。
 * 错误三分：
 * 1. server 发现失败（catalog.unavailable）→ 附原因；
 * 2. 单元/服务器未发现 → 「server 未连接或未发现」；
 * 3. 工具不存在 → 「tool 不存在」。
 * @param units 连接池单元集合。
 * @param root 目标 root（可为 @global）。
 * @param server @<root>/<server> 全名。
 * @param tool 远端工具裸名（兼容 mcp__ 前缀，复用 normalizeToolName）。
 */
export function findToolDetail(
  units: Map<string, ProjectUnit>,
  root: string,
  server: string,
  tool: string,
): ToolDetail {
  const {
    connection: { CATALOG_TTL_MS },
    workspace: { parseFullServerName, normalizeToolName },
  } = catalogPorts.get();
  const parsed = parseFullServerName(server);
  if (parsed === undefined || parsed.root !== root) {
    throw new Error(
      `ws_mcp_detail: server ${JSON.stringify(server)} 不属于当前工作空间 ${JSON.stringify(root)}；路由一致性校验失败（防跨空间串台）`,
    );
  }
  const unit = units.get(root);
  if (unit === undefined) {
    throw new Error(`ws_mcp_detail: server 未连接或未发现：${JSON.stringify(server)}`);
  }
  const catalog = catalogDirectory.entryFor(root, parsed.server);
  if (catalog === undefined || catalog.tools.size === 0) {
    if (catalog?.unavailable !== undefined) {
      throw new Error(
        `ws_mcp_detail: server 发现失败：${JSON.stringify(server)}（${catalog.unavailable}）`,
      );
    }
    if (unit.userDisabled.has(parsed.server)) {
      throw new Error(
        `ws_mcp_detail: server 未连接或未发现：${JSON.stringify(server)}（已被用户禁用）`,
      );
    }
    throw new Error(`ws_mcp_detail: server 未连接或未发现：${JSON.stringify(server)}`);
  }
  const toolName = normalizeToolName(parsed.server, tool, "ws_mcp_detail");
  const found = catalog.tools.get(toolName);
  if (found === undefined) {
    throw new Error(`ws_mcp_detail: tool 不存在：${JSON.stringify(`${server}/${toolName}`)}`);
  }
  const fresh = Date.now() - catalog.discoveredAt <= CATALOG_TTL_MS;
  const detail: ToolDetail = {
    server,
    tool: toolName,
    description: found.description,
    inputSchema: found.inputSchema,
    fresh,
  };
  if (unit.userDisabled.has(parsed.server)) detail.disabled = true;
  return detail;
}
// 两个纯函数（新鲜判定 / 装箱）自 #767 S1-3b 起物理落点在 impl/directory：
// 目录投影本体要用它们，而本文件要用目录读口——留在本文件会形成文件级值环。
// 公开导出面不变（仍经 catalog/interface.ts 从本文件转出）。
export { boundCatalogTools, isCatalogFresh } from "./impl/directory/index.ts";

