/**
 * dsh-mcp-manager — pipeline/impl/project/index.ts：CallToolResult 投影（单一事实源，#512，#664 阶段 2 迁入）。
 *
 * 原自 call-result.ts（全量迁移，含类型面）。MCP 协议对 tools/call 成功应答宽容
 * （content / structuredContent / isError / _meta 均 optional，各 SDK 序列化习惯
 * 不一——Python pydantic exclude_none 剔不掉合法值 isError:false）；dsh 工具契约
 * 要求 execute 返回精确匹配 output schema（additionalProperties:false），故在此
 * 收敛白名单投影（对齐官方 dsh-mcp-client createExecutor）。
 *
 * supervisor（mcp__ 直呼路径）与 middleware（ws_mcp_call 远端转发）共用；
 * 调用方差异（文本截断/提取、错误文案风格）经 CallResultTextHandlers 注入。
 */

/** 投影文本渲染回调（调用方差异面）。 */
export interface CallResultTextHandlers {
  /**
   * isError:true 的抛错文案（入参为 content 块数组，调用方按自身文案风格
   * 渲染；缺省用兜底文本抛错）。
   */
  errorText?: (content: unknown[]) => string;
  /**
   * content 缺失/非数组时的兜底文本渲染；缺省 defaultCallResultFallbackText
   * （supervisor 额外叠加截断）。
   */
  fallbackText?: (result: unknown) => string;
}

/** 投影产物：恰好落在 ws_mcp_call / mcp__ 工具的 output schema 契约内。 */
export interface ProjectedCallResult {
  content: unknown[];
  structuredContent?: unknown;
}

/**
 * 默认兜底文本：toolResult 形态渲染 JSON，否则 "(no output)"
 * （对齐官方 dsh-mcp-client 的 no-content 分支）。
 */
export function defaultCallResultFallbackText(result: unknown): string {
  const rendered =
    result !== undefined && result !== null && typeof result === "object" && "toolResult" in result
      ? JSON.stringify((result as { toolResult?: unknown }).toolResult)
      : "(no output)";
  return typeof rendered === "string" ? rendered : "(no output)";
}

/**
 * 默认错误文案：优先取 content 内 text 块 join（保留远端错误信息），
 * 无 text 块时退化兜底文本。轻量提取，不做占位符渲染（占位符渲染由调用方按
 * 自己的 handler 决定，不是本函数的职责）。
 */
function defaultErrorText(content: unknown[], fallbackText: string): string {
  const parts: string[] = [];
  for (const block of content) {
    if (
      typeof block === "object" &&
      block !== null &&
      (block as { type?: unknown }).type === "text" &&
      typeof (block as { text?: unknown }).text === "string"
    ) {
      parts.push((block as { text: string }).text);
    }
  }
  return parts.length > 0 ? parts.join("\n") : fallbackText;
}

/**
 * 把远端 CallToolResult 投影为 dsh 工具契约形状。
 * @param result protocol.callTool 的原始返回（宽松 ResultSchema，未定形）。
 * @param handlers 可选的文本渲染差异面。
 * @returns 白名单化的 { content, structuredContent? }（无 undefined 值键）。
 * @throws Error 当 result.isError === true（文案经 handlers.errorText 或兜底文本）。
 */
export function projectCallToolResult(
  result: unknown,
  handlers: CallResultTextHandlers = {},
): ProjectedCallResult {
  const resultObj = (typeof result === "object" && result !== null ? result : undefined) as
    | { content?: unknown; isError?: unknown; structuredContent?: unknown; toolResult?: unknown }
    | undefined;
  // 兜底文本惰性求值（F3）：仅缺省分支实际消费，正常 content 路径零开销。
  const resolveFallbackText = (): string =>
    handlers.fallbackText !== undefined
      ? handlers.fallbackText(result)
      : defaultCallResultFallbackText(result);
  const structured = resultObj?.structuredContent;
  if (!Array.isArray(resultObj?.content)) {
    // 无 content / 非数组 content：兜底文本分支（toolResult JSON 或占位符）。
    if (resultObj?.isError === true) throw new Error(resolveFallbackText());
    const fallbackText = resolveFallbackText();
    return {
      content: [{ type: "text", text: fallbackText }],
      ...(structured !== undefined ? { structuredContent: structured } : {}),
    };
  }
  if (resultObj?.isError === true) {
    const fallbackText = resolveFallbackText();
    throw new Error(
      handlers.errorText !== undefined
        ? handlers.errorText(resultObj.content)
        : defaultErrorText(resultObj.content, fallbackText),
    );
  }
  return {
    content: resultObj.content,
    ...(structured !== undefined ? { structuredContent: structured } : {}),
  };
}

/**
 * dsh-mcp-manager — pipeline/impl/redact/index.ts：凭据脱敏器（#664 阶段 2 迁入，B8 改口径同文件）。
 *
 * B8（D4 决策）：仅用户信息脱敏（username/password/searchParams），host/path
 * 无凭据保留可读（现状整 URL 脱敏，可诊断性差）；raw/decoded 双形态注册——
 * 错误消息中出现的是原始 URL 字节串（percent-encoding 形态），URL parse 拿到
 * decoded 形态，两者都须命中（否则 percent-encoding 绕过回归，评审 B8 修正）。
 */
import type { ServerConfig } from "../../../config/interface.ts";

/** 注册单个敏感值：decoded 形态 + percent-encoded raw 形态双注册。 */
function addSecretPair(secrets: Set<string>, value: string): void {
  if (value.length === 0) return;
  secrets.add(value);
  try {
    secrets.add(encodeURIComponent(value));
  } catch {
    // 编码失败（如孤立代理字符）忽略 raw 形态，decoded 已注册
  }
}

/** 长 flag 精确名集合（去横线小写后全等匹配。子串匹配会把 --turkey 当成含 key 误收下个参数作秘密，过度脱敏；#903 B-M2）。覆盖旧子串口径的全部常见形态。 */
const SECRET_FLAG_NAMES: ReadonlySet<string> = new Set([
  "token",
  "tokens",
  "secret",
  "secrets",
  "password",
  "passwd",
  "pass",
  "passphrase",
  "key",
  "keys",
  "apikey",
  "api-key",
  "secretkey",
  "secret-key",
  "auth",
  "authorization",
  "authtoken",
  "auth-token",
  "cookie",
  "cookies",
  "credential",
  "credentials",
  "access-token",
  "accesstoken",
  "client-secret",
  "clientsecret",
]);

/** 短 flag 精确集合（#903 B-M2：-p password 这类单字母形态旧口径漏收）。只认独占一拍的精确形态。 */
const SECRET_SHORT_FLAGS: ReadonlySet<string> = new Set(["-p", "-k", "-s"]);

/** flag 名是否为凭据形参（精确匹配；短 flag 另判）。 */
function isSecretFlagName(flag: string): boolean {
  return SECRET_FLAG_NAMES.has(flag.replace(/^-+/, "").toLowerCase());
}

/** 收集 stdio 形态服务器的 secret：回答「本地命令的秘密在哪？」——环境变量值
 * 全收 + 疑似凭据 flag 的参数值（`--token x` 与 `--token=x` 两种形态，另收 `-p/-k/-s` 短 flag 下一拍；长 flag 精确名匹配）；http 形态
 * （headers/URL 用户信息）的收集在 createRedactor 内（不同问题）。 */
function collectStdioSecrets(server: ServerConfig, secrets: Set<string>): void {
  for (const value of Object.values(server.env ?? {})) addSecretPair(secrets, value);
  const args = server.args ?? [];
  for (let index = 0; index < args.length; index += 1) {
    const argument = args[index] ?? "";
    if (SECRET_SHORT_FLAGS.has(argument)) {
      const value = args[index + 1];
      if (value !== undefined && value.length > 0) addSecretPair(secrets, value);
      continue;
    }
    const equals = argument.indexOf("=");
    const flag = equals < 0 ? argument : argument.slice(0, equals);
    if (!isSecretFlagName(flag)) continue;
    const value = equals < 0 ? args[index + 1] : argument.slice(equals + 1);
    if (value !== undefined && value.length > 0) addSecretPair(secrets, value);
  }
}

/** 凭据脱敏器：从服务器配置收集 secret 值，替换错误消息中的出现。 */
export function createRedactor(servers: readonly ServerConfig[]): (error: unknown) => string {
  const secrets = new Set<string>();
  for (const server of servers) {
    if (server.transport === "stdio") {
      collectStdioSecrets(server, secrets);
      continue;
    }
    for (const value of Object.values(server.headers ?? {})) addSecretPair(secrets, value);
    const url = server.url;
    if (typeof url === "string" && url !== "") {
      // B8：不加入整 URL——host/path 无凭据部分保留（错误消息可诊断）；
      // 仅用户信息（username/password/searchParams）脱敏。
      try {
        const parsed = new URL(url);
        addSecretPair(secrets, parsed.username);
        addSecretPair(secrets, parsed.password);
        for (const value of parsed.searchParams.values()) addSecretPair(secrets, value);
      } catch {
        // 非法 URL 忽略
      }
    }
  }
  const ordered = [...secrets].sort((left, right) => right.length - left.length);
  return (error: unknown): string => {
    let text: string;
    try {
      text = error instanceof Error ? error.message : String(error);
    } catch {
      text = "<unprintable error>";
    }
    for (const secret of ordered) text = text.split(secret).join("[REDACTED]");
    return text;
  };
}

/**
 * dsh-mcp-manager — pipeline/impl/service/index.ts：执行管道域端口持有者（#767 B2a-wire W5）。
 *
 * 域内实现经 `pipelinePorts.get()` 取数，写入只发生在组合根入口顶层的 `installPipeline`
 * （见 `src/index.ts`）。形态照 `server/upgrade/impl/service/` 与 `catalog/impl/service/`：
 * 模块级只有一个 `const` 实例、状态收进实例字段（I9），装配与复位只经方法（方法内赋值）。
 */
import type { PipelineDeps } from "../../deps.ts";

/** 执行管道域端口表：装配一次、域内多处读。 */
class PipelinePorts {
  /** 未装配时保持 undefined——「没装配」与「装配了空实现」必须可区分（I6）。 */
  private deps: PipelineDeps | undefined;

  /** 装配：组合根递入静态模块引用；重复装配是编程错误，当场暴露。 */
  install(deps: PipelineDeps): void {
    if (this.deps !== undefined) throw new Error("dsh-mcp-manager: pipeline 域只能装配一次");
    this.deps = deps;
  }

  /** 卸载：只复位装配标记，本域没有别的活资源要释放。 */
  release(): void {
    this.deps = undefined;
  }

  /**
   * 域内取数的唯一入口。未装配即抛错而不是回落默认值：默认值会让「组合根漏装」表现成
   * 行为正常但参数不对（全名解析与裸名回落静默换实现），症状与本插件毫无字面关联。
   */
  get(): PipelineDeps {
    const deps = this.deps;
    if (deps === undefined) {
      throw new Error(
        "dsh-mcp-manager: pipeline 域未装配——组合根未在入口调用 installPipeline（src/index.ts）",
      );
    }
    return deps;
  }
}

/** 本域唯一的装配实例：类不外放，外部 new 不出第二份端口表。 */
export const pipelinePorts = new PipelinePorts();

/**
 * dsh-mcp-manager — pipeline/impl/timeout/index.ts：调用超时兜底（#664 阶段 2 迁入）。
 *
 * 原自 middleware-utils.ts withTimeout；中间层 ws_mcp_call 与封装直呼的
 * abort 竞态处理单一实现（supervisor 路径靠 SDK timeoutMs，无此层）。
 */

/** 等待带超时（race 兜底）。 */
export function withTimeout<T>(
  promise: Promise<T>,
  ms: number,
  message: string,
  signal?: AbortSignal,
): Promise<T> {
  if (signal?.aborted === true) return Promise.reject(signal.reason ?? new Error("aborted"));
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => {
      cleanup();
      reject(new Error(message));
    }, ms);
    const onAbort = () => {
      cleanup();
      reject(signal?.reason ?? new Error("aborted"));
    };
    const cleanup = () => {
      clearTimeout(timer);
      signal?.removeEventListener("abort", onAbort);
    };
    signal?.addEventListener("abort", onAbort, { once: true });
    void promise.then(
      (value) => {
        cleanup();
        resolve(value);
      },
      (error) => {
        cleanup();
        reject(error);
      },
    );
  });
}

packages/dsh-mcp-manager/src/server/shar.source:
/**
 * 组合根机制：把宿主上下文收窄成能力面、按依赖顺序成对装配各域、逆序释放。
 *
 * 为什么不在 `src/index.ts`：包入口的**任何新导出**都会让 `export-surface-snapshot` 判红
 * （B1.4 的硬判据是入口导出面零 diff），而写在入口又不导出的函数测试不可达——夹具域驱动的探针
 * 必须 import 得到它。入口仍然是组合根：B2 由它调用这里的三个函数
 * （`bindHost(ctx)` → `assemble(host, domains)` → `ctx.effect(() => () => safeDisposeAll(disposers))`）。
 */
import type { Agent } from "@deepseek-ai/dsh-agent";
import type {
  AttachmentsPort,
  HostContextPort,
  HostFaces,
  ModelInfoPort,
  MountedPlugin,
  OfficialPluginModule,
} from "./host-faces.ts";

/**
 * 宿主 loader 服务的收窄面：本包不引官方 loader 的类型（`@deepseek-ai/cordis-plugin-loader` 不在
 * catalog、仓库内不可解析），只认运行时真要用到的那一个方法。
 */
interface ResolvedLoader {
  /** 按包名解析模块；官方实现可能同步返回，故一律按 `await` 消费。 */
  import(specifier: string): unknown;
}

/**
 * `ctx.plugin` 的编译期插件面。
 *
 * 为什么必须就地收窄转型：`ctx.plugin<P extends Plugin>` 的配置形参由 `GetPluginConfig<P>` 从
 * 插件体签名反推，而 `OfficialPluginModule` 的成员全可选——推不出 `Plugin.Object` 那一支，配置位
 * 退化成 `never`，结构类型因此直接过不去。运行时官方插件的契约只有「带 `apply` 的对象」一条，
 * 所以这里只替换编译期推导，不放宽任何运行时校验。
 */
interface MountableOfficialPlugin {
  apply(ctx: unknown, config: unknown): unknown;
}

/**
 * 一个域给组合根的装配对。
 *
 * `install` / `release` **成对**：`install` 收本域需要的外部能力，`release` 复位本域**自己的**
 * 装配标记并放开入参。没有配对的下半截，域就只能在下次装配时静默复用上一次的状态。
 */
export interface DomainSpec<Host = HostFaces> {
  /** 域标识：只用于装配错误文案，域内断言不依赖它。 */
  readonly name: string;
  /** 装配。入参是组合根收窄后的宿主能力面——域拿不到 `Context`。 */
  install(host: Host): void | Promise<void>;
  /** 释放：与 `install` 配对，复位本域标记；重复调用无害。 */
  release(): void;
}

/**
 * 把宿主上下文收窄成能力面。
 *
 * 交付的是**能力**而不是装配期算好的值：算一次的快照看起来与实时读取一模一样，却在用户改了设置
 * 之后继续用旧值（E.2 实测：`webServer.register` 的摘除器、`ctx.tools` 的注册表都是活对象）。
 */
export function bindHost(ctx: HostContextPort): HostFaces {
  return {
    logger: ctx.logger,
    logs: {
      capture: (handler) => {
        // 摘除器类型是 Disposable<Promise<void>>（宿主按 fiber 回收）；本包只承诺同步摘除语义，
        // 异步那一半由宿主自己的 effect 负责——把 Promise 递到域里只会让域多一个不该管的等待点。
        //
        // 必须显式给 levels：宿主的投递闸是
        // `(exporter.levels?.[name] ?? exporter.levels?.default ?? 发出方 level ?? 1) < level` 即丢，
        // 不写就落到发出方缺省 INFO(1)，而官方客户端的重连提示是 warn(2)——整条诊断面会只剩
        // error 级、把「正在退避重试」这类最需要让用户看到的话全丢掉。取 2（error/info/warn）：
        // debug(3) 是官方内部噪音，不属于诊断口径。
        const dispose = ctx.logger.exporter({
          levels: { default: 2 },
          export: (message) => handler(message),
        });
        return () => {
          void dispose();
        };
      },
    },
    register: { register: (route) => ctx.webServer.register(route) },
    tools: {
      register: (definition) => ctx.tools.register(definition),
      // 现读宿主注册表而不是装配期快照：六态投影靠它判「该 id 下已有注册工具」（设计 §3.1 输入面 B）。
      // scope 原样转交：省略 scope 是查询方的语义选择，绑定层不得替它把参数丢掉。
      schemas: (scope) => ctx.tools.schemas(scope),
    },
    prompt: { section: (section) => ctx.systemPrompt.section(section) },
    expose: { provide: (name, service) => ctx.provide(name, service) },
    events: {
      onPreStep: (handler) => ctx.on("agent/pre-step", handler),
      // agent 作用域边：restrict 只在**作用域**上下文上可用（全局调用被宿主当场拒），故这里把
      // agent 自己的 tools 面连同 id 一起交出去——域拿不到 Context，也就没有第二处作用域入口。
      onAgentCreated: (handler) =>
        ctx.on("agent/created", ({ agent }) => handler({ id: agent.id, tools: agent.ctx.tools })),
      onAgentDisposed: (handler) =>
        ctx.on("agent/disposed", ({ agent }) => handler({ id: agent.id })),
      onToolsChange: (handler) => ctx.on("tools/change", handler),
      // 装载时的全量 reconcile 用：同名服务缺席（假 ctx / 早期装配）时给空表，不抛。
      liveAgents: () => {
        // 假 ctx 常见：`get` 本身缺席（宿主服务查询面不可用）——给空表，不抛。
        if (typeof ctx.get !== "function") return [];
        const agents = ctx.get("agents") as { list(): readonly Agent[] } | undefined;
        return (agents?.list() ?? []).map((agent) => ({ id: agent.id, tools: agent.ctx.tools }));
      },
    },
    // 晚读 thunk（不是装配期快照）：attachments/llm 都是晚到服务，apply 期取恒 undefined。
    attachments: () => ctx.get("attachments") as AttachmentsPort | undefined,
    models: () => ctx.get("llm") as ModelInfoPort | undefined,
    loader: {
      load: async (specifier) => {
        // `loader` 不在 `Context` 类型面上，只能按名字现取；取不到就 fail closed——回落
        // `undefined` 会把「宿主没装配 loader」表现成「这个包名不存在」，把装配错误推迟到现场。
        const loader = ctx.get("loader") as ResolvedLoader | undefined;
        if (loader === undefined || loader === null) {
          throw new Error(
            "dsh-mcp-manager: 宿主未提供 loader 服务，无法按包名解析官方 MCP 客户端——" +
              "裸包名只有 loader 能解析（锚 ctx.baseUrl）",
          );
        }
        return (await loader.import(specifier)) as OfficialPluginModule;
      },
      mount: (module, config) => {
        const fiber = ctx.plugin(module as MountableOfficialPlugin, config);
        // dispose 只置位不回滚：晚到的 ready 结算据此判断还能不能改状态。
        const state = { disposed: false };
        const handle: MountedPlugin = {
          ready: fiber.await().then(() => undefined),
          get disposed() {
            return state.disposed;
          },
          async dispose() {
            state.disposed = true;
            await fiber.dispose();
          },
        };
        // 兜底回收链：宿主卸载本插件时跑。某个域漏了 release，官方实例也不会活到下一次装配——
        // 它持有的子进程与 serverName 预留都随此释放。
        ctx.effect(
          () => () => {
            void handle.dispose();
          },
          "dsh-mcp-manager: loader mount",
        );
        return handle;
      },
    },
  };
}

/**
 * 按依赖顺序装配各域，返回它们的释放函数（逆序交给 `safeDisposeAll`）。
 *
 * `install` 一律 `await`：`upgrade` 域的装配是异步的（落盘原语只有 Promise 面），不等待就等于
 * 让各域在存储迁移跑完之前去读旧布局——那时旧文件已被归档，读到的是空盘。
 *
 * 装配期不吞错：任一步抛错即中止，已装好的域保持已装状态——各域的 `install` 都保证「抛错等于没装」
 * （标记在最后一步才置位），宿主重试装配时从同一步重跑。
 */
export async function assemble<Host>(
  host: Host,
  domains: readonly DomainSpec<Host>[],
): Promise<Array<() => void>> {
  const seen = new Set<string>();
  const disposers: Array<() => void> = [];
  for (const domain of domains) {
    // 同一个域在一次装配里出现两次 = 装配表写错了，放过去就是两份能力挂在同一份状态上。
    if (seen.has(domain.name)) {
      throw new Error("dsh-mcp-manager: 装配表里 " + domain.name + " 域出现了两次");
    }
    seen.add(domain.name);
    await domain.install(host);
    disposers.push(() => {
      domain.release();
    });
  }
  return disposers;
}

/**
 * 逐个释放；单个释放失败不阻断其余（否则一个域的清理会拖垮整条卸载链）。
 *
 * **逆序**：后装的先释放，否则出口域会在别人已经放开的入参上继续服务。
 */
export function safeDisposeAll(disposers: readonly (() => void)[]): void {
  for (const dispose of [...disposers].reverse()) {
    try {
      dispose();
    } catch {
      // 卸载阶段不做失败上报：首因已经发生，再抛一个只会把它盖掉。
    }
  }
}

/**
 * dsh-mcp-manager — server/shared/constants.ts：跨域共享纯常量单一事实源。
 *
 * 为什么落共享层而不是留在原域：这几个默认值被 config 域在**模块求值期**消费
 * （`z.object({...}).default(CONST)`，见 server/config/config-schema.ts）——端口注入要等装配
 * 完成，那时 schema 早已求值，物理上只能拿到 undefined（HB1）；而留在原域让消费方直接 import，
 * 就是 I2① 的跨域值边（config → catalog、config → connection）。唯一可行形态是
 * 「共享层单点定义 + 消费方从共享层取」。
 *
 * LIST_DEFAULT_TOOLS_PER_SERVER 的落点依据是同一条值面门槛（I5：被 ≥2 域消费的值常量归共享层）：
 * catalog（检索装箱）与 inject（ws_mcp_list 工具定义）两域消费它，留在 connection/runtime 就是两条
 * 跨域值边。它不是模块求值期常量，落这里只为消除两条边并把定义收成一处。
 *
 * 为什么本文件零 import：它落在 config 域的模块求值路径上，本文件必须是**最先可求值**的
 * 叶子——任何依赖都会把初始化顺序与值环重新引回来。
 */

/** 能力目录默认开启；为什么不启用端口：见本文件头注释。 */
export const DEFAULT_ANNOUNCE_CATALOG = true;
/** 能力目录最大条目数（防上下文膨胀）。 */
export const DEFAULT_CATALOG_MAX_ENTRIES = 6;
/** 默认单次工具调用超时（毫秒）。下探自 60s：死工具（服务器已断线但工具未注销）
 * 会让模型阻塞一整轮；15s 内快速失败并携带"服务器不可用"说明更划算。 */
export const DEFAULT_TOOL_CALL_TIMEOUT_MS = 15_000;
/**
 * 连接等待超时（毫秒）。从 connection/runtime/limits.ts 上移（#767 S1-2b）：换引擎后连接不再由
 * 我方协议栈持有，这个预算只能包在官方句柄的 ready 上，消费方变成 servers/lifecycle 与仍在的
 * runtime 子层——两处消费按 I5 归共享层，物理定义因此只剩这一份。
 */
export const CONNECT_TIMEOUT_MS = 10_000;
/**
 * 工具发现超时（毫秒）。同上上移（#767 S1-2b）；换引擎后这个预算由官方插件在 ready 内结算，
 * 本包保留常量出口供 runtime 子层与 inject 消费，新的等待窗口不再拿它轮询（理由见
 * servers/lifecycle/impl/timeout）。
 */
export const DISCOVERY_TIMEOUT_MS = 10_000;
/** 工具结果渲染截断上限（字节）。extractText 现状不截断，超长 JSON 全量进上下文。 */
export const DEFAULT_RESULT_TRUNCATE_BYTES = 8192;
/** ws_mcp_list 每服务器工具条数默认上限（catalog 与 inject 两域消费，见本文件头注释）。 */
export const LIST_DEFAULT_TOOLS_PER_SERVER = 50;
/**
 * MCP 服务器注册名（官方 dsh-mcp-client 的 serverName）命名空间约束，与官方逐字同源。
 * 从 config/normalize.ts 上移（#767 S1-4a）：workspace 域的 id 生成器要用**同一份**判定，
 * 留在 config 域就会多出一条 workspace → config 的跨域值边（I2① 判红），而重抄一份正则等于
 * 两个物理定义、会静默漂移。config 域门面照旧转出同名符号，既有调用点不变。
 */
export const SERVER_NAME_PATTERN = /^[A-Za-z0-9_-]{1,32}$/;
/**
 * 官方 dsh-mcp-client 的包名（交给 loader 按名解析的**说明符**，不是 import 语句）。
 *
 * 落共享层是因为消费方在 servers/lifecycle：官方包不在 catalog、仓库内不可解析，只能经
 * loader 的 baseUrl 按名解析（设计 §1.1），而这条说明符必须与其他配置面口径同源——散在
 * 消费方里就会随重构复制出第二份，改包名时只改一处才谈得上一致性。测试同样经共享层门面取，
 * 不重抄字面量。
 */
export const OFFICIAL_MCP_CLIENT_SPECIFIER = "@deepseek-ai/dsh-mcp-client";
/**
 * 官方 dsh-mcp-client 在宿主日志面上的记录名（cordis 日志记录的 `name` 字段）。
 *
 * 换引擎后本插件拿不到官方的状态 API 与错误对象，官方「说了什么」只剩日志这一条通道；而
 * 每条官方日志都带 `mcp-client(<serverName>)` 前缀。落共享层是为了让归属判定与「交给官方的
 * serverName 就是我方 id」这条事实同源——散在消费方里就会随重构复制出第二份。
 */
export const OFFICIAL_MCP_CLIENT_LOG_NAME = "mcp-client";

/**
 * 落盘 IO 原语：原子写 + 容错读。
 *
 * 为什么自写而不引库：三个候选各自缺一项——`atomically` 在模块加载期就接管宿主退出路径、
 * `write-file-atomic` 没有写队列、`steno` 不收 mode 且合并写（§7.5 的比较表）。自写只比
 * 现状多一条串行链，换来「零依赖 + 不装进程级钩子 + 显式 mode」。
 *
 * 写函数恒定四件事：唯一临时名 → 显式 mode 写入 → `rename` 覆盖 → 失败清理临时名并上抛
 * **原错误**。同目标路径的写串行：`rename` 的先后在并发下没有保证，旧数据可能覆盖新数据（R11）。
 */
import { randomBytes } from "node:crypto";
import { mkdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import { dirname } from "node:path";
import { directoryMode, fileMode } from "./paths.ts";

/**
 * 同目标路径的写链。这是**模块级**的（I9 的例外）：串行必须跨调用点生效，收进实例反而各写各的。
 * 前一次 settle 之后才发起下一次；前一次失败不阻断下一次（链本身不能被一次失败毒化）。
 */
const writeChains = new Map<string, Promise<void>>();

/** 唯一临时名：pid + 时间戳 + 随机后缀——同名临时文件绝不会被两次写共用。 */
function temporaryNameFor(file: string): string {
  return `${file}.${process.pid}.${Date.now().toString(36)}.${randomBytes(6).toString("hex")}.tmp`;
}

/** 建目录并落登记的 mode：插件自有目录 0o700，项目 `.dsh/` 随项目自身权限模型。 */
export async function ensureDir(dir: string): Promise<void> {
  const mode = directoryMode(dir);
  await mkdir(dir, mode === null ? { recursive: true } : { recursive: true, mode });
}

/** 单次写（不含串行）：失败清理临时名后上抛原错误，残留临时名不留给下一次写踩踏。 */
async function writeOnce(file: string, data: string): Promise<void> {
  // 落在任何落盘动作之前：未登记的路径不该先建目录、再抛错。
  const mode = fileMode(file);
  await ensureDir(dirname(file));
  const temporary = temporaryNameFor(file);
  try {
    await writeFile(
      temporary,
      data,
      mode === null ? { encoding: "utf8" } : { encoding: "utf8", mode },
    );
    await rename(temporary, file);
  } catch (cause) {
    // 清理失败不掩盖原错误：调用方要看到的是「为什么没写成」，不是「清理也没成」。
    await rm(temporary, { force: true }).catch(() => undefined);
    throw cause;
  }
}

/** 原子写全文：mode 取自 `paths.ts` 的登记表，未登记即抛错（不写权限未登记的文件）。 */
export function writeFileAtomic(file: string, data: string): Promise<void> {
  const previous = writeChains.get(file) ?? Promise.resolve();
  const next = previous.then(
    () => writeOnce(file, data),
    () => writeOnce(file, data),
  );
  writeChains.set(file, next);
  return next.finally(() => {
    if (writeChains.get(file) === next) writeChains.delete(file);
  });
}

/** 容错读全文：不存在 / 不可读 / 是目录一律回落 null，由各域按既有语义回落空值。 */
export async function readTextFile(file: string): Promise<string | null> {
  try {
    return await readFile(file, "utf8");
  } catch {
    return null;
  }
}

/** 容错读 JSON：解析失败同样回落 null——坏文件是各域读面的常态，不是进程失败。 */
export async function readJsonFile<T>(file: string): Promise<T | null> {
  const text = await readTextFile(file);
  if (text === null) return null;
  try {
    return JSON.parse(text) as T;
  } catch {
    return null;
  }
}

/**
 * 存储布局与权限的单一事实源（I7）。
 *
 * 文件名与 mode 都是迁移契约：散在调用点就会各自漂移，漂移的那一次是「迁移读空」或
 * 「权限随 umask 静默变化」。旧路径与目标路径因此在同一处声明——`upgrade` 域只搬字节、
 * 不认字面量。根目录只认 `DSH_HOME` 一个变量（经仓库共享层 `shared/dsh-home.js`），
 * 隔离验证换掉它即换掉全部落盘位置。
 */
import { basename, dirname, join } from "node:path";
import { dshHome } from "../../../../../shared/dsh-home.js";

/** 本插件在 DSH home 下的私有目录：按 npm 包名分区，不与其它插件争用根目录。 */
const PACKAGE_DIR = "@wingsky-1/dsh-mcp-manager";

/** 私有目录权限：同机其它用户不得列举本插件的落盘面（与 mcp.json 的 0o600 同族）。 */
export const PACKAGE_DIR_MODE = 0o700;

/** 目标布局的文件名（迁移契约）。 */
export const CONFIG_FILE_NAME = "mcp.json";
export const USER_STATE_FILE_NAME = "user-state.json";
export const CATALOG_DIR_NAME = "catalog";
export const CATALOG_SUMMARY_FILE_NAME = "catalog-summary.json";
export const STATS_FILE_NAME = "stats.json";
export const VERSION_FILE_NAME = "version";

/**
 * 项目级配置的新形态：`<项目根>/.dsh/@wingsky-1/dsh-mcp-manager/mcp.json`（按包分区，
 * 与全局私有目录同构）。旧扁平形态 `<项目根>/.dsh/mcp.json` 见 `legacyProjectConfigFile`——
 * 只做迁移读面，不回写。
 */
const PROJECT_CONFIG_DIR_NAME = ".dsh";
const PROJECT_CONFIG_FILE_NAME = "mcp.json";

/**
 * 旧版布局清单（迁移的**读面**，新代码不得回写）：两类用户数据散在 DSH home 根。
 *
 * 收缩依据：目录摘要与调用统计可再生、不进迁移（见计划 §2.3）；目录型旧路径
 * `dsh-mcp-catalog/` 同理可再生，随本笔一并退出迁移面。
 */
export const LEGACY_LAYOUT = {
  config: "dsh-mcp.json",
  userState: "dsh-mcp-user-state.json",
} as const;

/** 本插件私有目录。 */
export function mcpManagerHome(): string {
  return join(dshHome(), PACKAGE_DIR);
}

/** 私有目录下的一个文件（只有本模块知道名字，故不对外暴露）。 */
function mcpManagerFile(fileName: string): string {
  return join(mcpManagerHome(), fileName);
}

/** 全局服务器配置：本包最敏感的一档（含 env 引用与凭据字段）。 */
export function configFile(): string {
  return mcpManagerFile(CONFIG_FILE_NAME);
}

/**
 * 用户状态（disabledTools 等）。
 *
 * 名字用 Path 而不是 File：入口今天仍导出旧实现 `userStateFile()`（返回旧路径），两个同名函数
 * 在迁移期同时存在会让「拿到的是新路径还是旧路径」无从判读，导出面门禁也会看到两个同名定义块。
 */
export function userStatePath(): string {
  return mcpManagerFile(USER_STATE_FILE_NAME);
}

/** 目录 last-good 缓存的**目录**（每工作空间一份 `<hash>.json`）。 */
export function catalogDir(): string {
  return mcpManagerFile(CATALOG_DIR_NAME);
}

/** 目录 last-good 缓存文件。 */
export function catalogFile(hash: string): string {
  return join(catalogDir(), `${hash}.json`);
}

/** 目录摘要缓存。 */
export function catalogSummaryFile(): string {
  return mcpManagerFile(CATALOG_SUMMARY_FILE_NAME);
}

/** 调用统计。 */
export function statsFile(): string {
  return mcpManagerFile(STATS_FILE_NAME);
}

/** 存储版本刻度（升级链走到哪一版，不是插件版本——后者读 package.json）。 */
export function versionFile(): string {
  return mcpManagerFile(VERSION_FILE_NAME);
}

/** 项目级服务器配置：包分区新形态（迁移目标，写面只认它）。 */
export function projectConfigFile(projectRoot: string): string {
  return join(projectRoot, PROJECT_CONFIG_DIR_NAME, PACKAGE_DIR, PROJECT_CONFIG_FILE_NAME);
}

/**
 * 项目级旧扁平形态（迁移**读面**，新代码不得回写）：`isProjectConfigFile` 只认新形态，
 * 故写函数天然拒绝它——与全局 LEGACY_LAYOUT 的「旧路径只读」同族。
 */
export function legacyProjectConfigFile(projectRoot: string): string {
  return join(projectRoot, PROJECT_CONFIG_DIR_NAME, PROJECT_CONFIG_FILE_NAME);
}

/** 旧版布局下的一个文件（DSH home 根）。 */
export function legacyFile(fileName: string): string {
  return join(dshHome(), fileName);
}

/** mode 登记表的一行。`null` = 登记了「不设 mode」（该项目随项目自身的权限模型）。 */
type ModeEntry = { readonly matches: (path: string) => boolean; readonly mode: number | null };

/**
 * 项目级配置的路径形态：项目根是用户数据、不能枚举，故按三级目录名识别——文件名
 * `mcp.json` + 父目录包分区目录 + 祖父的父目录 `.dsh`。旧扁平形态不在此列（只读）。
 *
 * 注：`PACKAGE_DIR` 含 `/`（`@wingsky-1/dsh-mcp-manager`），`basename` 只取末段比较，
 * 祖父层用两次 `dirname` 跳过中间的 `@wingsky-1` 一级——字面量比较 `basename(dir) ===
 * PACKAGE_DIR` 恒为假，故此处按段比较。
 */
function isProjectConfigFile(path: string): boolean {
  if (basename(path) !== PROJECT_CONFIG_FILE_NAME) return false;
  const leafDir = dirname(path);
  return (
    basename(leafDir) === basename(PACKAGE_DIR) &&
    basename(dirname(dirname(leafDir))) === PROJECT_CONFIG_DIR_NAME
  );
}

/**
 * 逐文件 mode 表（§7.1）。catalog 一族按**父目录**登记，`catalog/<hash>.json` 只占一行。
 *
 * 为什么不给写函数兜底默认值：兜底 = 权限随 umask 漂移而调用点毫无感觉，这条静默行为正是
 * mode 表要消除的；未登记一律抛错（I6）。
 */
const FILE_MODES: readonly ModeEntry[] = [
  { matches: (path) => path === configFile(), mode: 0o600 },
  { matches: (path) => path === userStatePath(), mode: 0o644 },
  { matches: (path) => dirname(path) === catalogDir(), mode: 0o644 },
  { matches: (path) => path === catalogSummaryFile(), mode: 0o644 },
  { matches: (path) => path === statsFile(), mode: 0o644 },
  { matches: (path) => path === versionFile(), mode: 0o644 },
  { matches: (path) => isProjectConfigFile(path), mode: null },
];

/** 目标文件的登记 mode；未登记即抛错，写函数不替调用点做权限决定。 */
export function fileMode(file: string): number | null {
  const entry = FILE_MODES.find((candidate) => candidate.matches(file));
  if (entry === undefined) {
    throw new Error(`落盘路径未登记 mode（先加入 server/shared/paths.ts 的登记表）：${file}`);
  }
  return entry.mode;
}

/**
 * 目标目录的登记 mode：插件自有目录 0o700；项目 `.dsh/` 及其下的包分区叶子目录随项目
 * （null）；未登记即抛错。
 *
 * 注：`PACKAGE_DIR` 含 `/`，`basename(dir) === PACKAGE_DIR` 恒为假，故按末段 +
 * 祖父层 `.dsh` 双条件识别（与 `isProjectConfigFile` 同形）。`ensureDir` 只校验传入的
 * 那一级目录，叶子登记 null 即够（`mkdir recursive` 建中间级不另校验）。
 */
export function directoryMode(dir: string): number | null {
  if (dir === mcpManagerHome() || dir === catalogDir()) return PACKAGE_DIR_MODE;
  if (basename(dir) === PROJECT_CONFIG_DIR_NAME) return null;
  if (
    basename(dir) === basename(PACKAGE_DIR) &&
    basename(dirname(dirname(dir))) === PROJECT_CONFIG_DIR_NAME
  ) {
    return null;
  }
  throw new Error(`落盘目录未登记 mode（先加入 server/shared/paths.ts 的登记表）：${dir}`);
}

/**
 * dsh-mcp-manager — server/shared/tool-names.ts：模型可见注册名的唯一派生点。
 *
 * 为什么落共享层：中间层转发与虚拟单元注册都按同一个名字查表，规则一旦出现第二份，
 * 某些工具就会永远查不到——名字是键，不是展示文本。
 *
 * 为什么不进 constants.ts：本文件依赖 node:crypto（超长名的哈希回退），而 constants.ts
 * 处在 config 域的模块求值路径上，必须保持零 import。
 */

import { createHash } from "node:crypto";

/** DeepSeek 函数名契约：最多 64 字符、仅 [A-Za-z0-9_-]。 */
const MAX_PUBLIC_NAME_LENGTH = 64;
const INVALID_NAME_CHARS = /[^A-Za-z0-9_-]/g;
const HASH_LENGTH = 12;

/** 从 (serverName, rawName) 派生模型可见的公开工具名。 */
export function publicToolName(serverName: string, rawName: string): string {
  const joined = `mcp__${serverName}__${rawName}`;
  const normalized = joined.replace(INVALID_NAME_CHARS, "_");
  if (normalized === joined && normalized.length <= MAX_PUBLIC_NAME_LENGTH) return normalized;
  const hash = createHash("sha256")
    .update(`${serverName}\0${rawName}`)
    .digest("hex")
    .slice(0, HASH_LENGTH);
  return `${normalized.slice(0, MAX_PUBLIC_NAME_LENGTH - HASH_LENGTH - 1)}_${hash}`;
}

