/**
 * upgrade 域升级链驱动：读刻度 → 取刻度仍停在起点的步骤 → 逐步执行并回写刻度 → 与插件版本对账。
 * **任何一步失败即抛出，启动随之中止**（存储没升完就被按错误形态解释，比不启动糟得多）；步骤按
 * **目标版本**排序执行，不按声明顺序。
 */
import type { UpgradeDeps, UpgradeLogger } from "../../deps.ts";
import { STEPS } from "../steps/index.ts";
import {
  compareVersions,
  pluginVersion,
  readStoredVersion,
  writeStoredVersion,
} from "../version/index.ts";
import type { UpgradeStep } from "./type.ts";

/**
 * 装配前跑一遍升级链（组合根在 `apply` 期 `await`）。必须在各域装配**之前**：升级会重写存储文件，
 * 先装配就等于让各域先读到旧形态，再让它们带着旧形态继续跑。
 */
export async function runUpgradeChain(deps: UpgradeDeps): Promise<void> {
  const recorded = await readStoredVersion();
  for (const step of pendingSteps(STEPS, recorded)) await applyStep(step, deps);
  reportGap(await readStoredVersion(), pluginVersion(), deps.logger);
}

/**
 * 刻度还停在这一步起点或更早的待办步，按**目标版本升序**（声明顺序只是便于阅读，不是执行顺序——
 * 漏排序会让后一步读到前一步尚未改进的形态）。步骤表作为入参是为了让本域用例能直接喂合成表，
 * 断言排序与起点边界；对外契约面仍只有 `installUpgrade` / `releaseUpgrade`。
 */
export function pendingSteps(steps: readonly UpgradeStep[], recorded: string): UpgradeStep[] {
  return [...steps]
    .sort((left, right) => compareVersions(left.targetVersion, right.targetVersion))
    .filter((step) => compareVersions(step.fromVersion, recorded) >= 0);
}

/**
 * 执行一步，成功后回写刻度。回写在 `run` **之后**而不是之前：刻度是「这一步做完了」的凭证，
 * 先写刻度等于把凭证发给一件还没做完的事，而失败时那个刻度会让下次启动跳过它。失败与回写失败
 * 都带上目标版本，是为了让「哪一步」出现在启动失败的现场。
 */
async function applyStep(step: UpgradeStep, deps: UpgradeDeps): Promise<void> {
  try {
    await step.run(deps);
  } catch (cause) {
    throw new Error(`dsh-mcp-manager: 存储升级到 ${step.targetVersion} 失败 — ${reasonOf(cause)}`, {
      cause,
    });
  }
  try {
    await writeStoredVersion(step.targetVersion);
  } catch (cause) {
    throw new Error(
      `dsh-mcp-manager: 存储版本号回写失败（${step.targetVersion}）— ${reasonOf(cause)}`,
      { cause },
    );
  }
}

/** 失败现场要的是消息，不是异常对象本身；非 Error 抛出物（字符串、undefined）也要落到文案里。 */
function reasonOf(cause: unknown): string {
  return cause instanceof Error ? cause.message : String(cause);
}

/**
 * 链跑完后的对账。三种落差分开报，因为它们要人去改的地方完全不同：落后 = 这一步的升级函数还没写
 * （开发期漏项）；超前且步骤表本身也超前 = 步骤表与 package.json 没同步；超前而步骤表没超前 =
 * 装的是更旧的包（降级）。三者都不中止启动——它们不是迁移动作失败，而静默地把刻度改成看起来对的值更糟。
 */
export function reportGap(recorded: string, target: string, logger: UpgradeLogger): void {
  const gap = compareVersions(recorded, target);
  if (gap === 0) return;

  if (gap < 0) {
    logger.warn(
      `dsh-mcp-manager: 存储版本 ${recorded} 落后于插件版本 ${target}，缺少对应的升级步骤`,
    );
    return;
  }

  const newest = newestTargetVersion(STEPS);
  if (newest !== "" && compareVersions(newest, target) > 0) {
    logger.warn(
      `dsh-mcp-manager: 升级链的目标版本 ${newest} 高于插件版本 ${target}（存储已升到 ${recorded}）——步骤表与 package.json 不同步`,
    );
    return;
  }
  logger.warn(`dsh-mcp-manager: 存储版本 ${recorded} 高于插件版本 ${target}，本插件的升级链不回退`);
}

/** 步骤表里最高的目标版本；空表时给空串。 */
function newestTargetVersion(steps: readonly UpgradeStep[]): string {
  let newest = "";
  for (const step of steps) {
    if (newest === "" || compareVersions(step.targetVersion, newest) > 0) {
      newest = step.targetVersion;
    }
  }
  return newest;
}

/** upgrade 域生命周期：装配期跑完升级链。链动的是磁盘上的文件，落盘原语是 Promise 面，故装配是异步的。 */
import type { UpgradeDeps } from "../../deps.ts";
import { runUpgradeChain } from "../chain/index.ts";

/** 升级域：装配期一次，此后没有活要干。 */
class UpgradeRunner {
  /** 是否已装配；单例实例重复装配是编程错误，当场暴露。 */
  private installed = false;

  /** 装配：先跑链。链在标记装配完成之前跑——它抛错时这次装配等于没发生，宿主重试装配才有机会重跑链
   * （链是幂等的，重跑不会累积归档名、也不会拿旧文件盖回目标）。 */
  async install(deps: UpgradeDeps): Promise<void> {
    if (this.installed) throw new Error("dsh-mcp-manager: upgrade 域只能装配一次");
    await runUpgradeChain(deps);
    this.installed = true;
  }

  /** 卸载：本域没有需要释放的东西——它只写了文件。 */
  release(): void {
    this.installed = false;
  }
}

/** 本域唯一的装配实例：类不外放，外面 `new` 不出第二份升级流程。 */
export const upgradeRunner = new UpgradeRunner();

/**
 * upgrade 域：项目级配置归位——把旧扁平形态 `<项目根>/.dsh/mcp.json` 收进包分区形态
 * `<项目根>/.dsh/@wingsky-1/dsh-mcp-manager/mcp.json`（§2.3）。
 *
 * Just-in-time 迁移：调用方（S2-b 经 orchestrator 端口接线）在读写项目级配置前调它；
 * 本笔只落函数 + 单测，不接调用方。语义直接复用 `settleOne`：目标存在→只归档不覆盖 /
 * 源缺→**不建初始形态**（initial=null；项目级缺文件即空 store，见
 * `server/store/impl/store.ts:41-47`，建空文件会改变「外部删除=清空配置」语义）/
 * 否则搬运 + 归档 `.migrated.bak`。
 */
import { legacyProjectConfigFile, projectConfigFile } from "../../../shared/interface.ts";
import type { UpgradeLogger } from "../../deps.ts";
import { settleOne } from "./storage-layout.ts";

/**
 * 落定一份项目级配置（幂等，语义见 `settleOne`）。
 *
 * 为什么不是 `export async function`：与 `installUpgrade` 同因——注入面对账
 * （`verify-dir-imports` 的 `analyzeInjectionFaces`）按 `export function installXxx(`
 * 采点，`async` 前缀会让这条对账静默失明——签名保持同步形态、返回值是 Promise。
 */
export function settleProjectConfig(root: string, logger: UpgradeLogger): Promise<void> {
  return settleOne(legacyProjectConfigFile(root), projectConfigFile(root), null, {
    logger,
    // settle 路径只用 logger：`storePath` 传空串——takenOver 是 LAYOUT 层的概念，
    // 与项目级无关。
    storePath: "",
  });
}

/**
 * 项目级配置的 settle 作用域包装（#767 S2-D，反转装饰）：先落定包分区新形态、
 * 再跑读动作，两段 `await` 串行——触发时机由包装内卡，调用方只给「落定后读什么」。
 *
 * 为什么是回调形态而不是直接回 store：本域不认业务（复核 1a）——`new McpStore`
 * 留在调用方（manager 经既有 ConfigStorePort），本域只递落定后的新形态路径；
 * 因此本文件零值 import store（M0a 护栏），读动作的失败语义也归调用方。
 *
 * 失败穿透：落定失败即抛，读回调不执行——禁回落 undefined（fail-closed 冲突 +
 * 重试风暴，复核 1d）；仅 reload 路保留有声 warn（见 manager 的缓存命中分支）。
 *
 * 为什么不是 `export async function`：与 `settleProjectConfig` 同因——注入面对账
 * 按 `export function installXxx(` 采点，保持同步形态返回 Promise。
 */
export function withSettledProjectConfig<T>(
  root: string,
  logger: UpgradeLogger,
  useSettled: (settledPath: string) => Promise<T>,
): Promise<T> {
  return settleProjectConfig(root, logger).then(() => useSettled(projectConfigFile(root)));
}

/**
 * upgrade 域：存储布局归位——把散在 DSH home 根目录的用户数据收进包私有目录（§7.1/§7.2）。
 *
 * 两条判据在这里落地：**纯字节搬移**（不 `JSON.parse`：坏文件的格式知识属各域容错读面，迁移把它原样
 * 搬到新位置）、**归档一律执行**（目标已存在时也不覆盖目标，旧文件改成固定名留痕 = 幂等标记）。
 *
 * 可再生落点（目录摘要 / 调用统计 / 目录型缓存）不进迁移：缺了由各域按空形态重建，搬旧值
 * 反而可能把过期快照当成新数据。
 */
import { existsSync, readFileSync, renameSync, statSync } from "node:fs";
import {
  LEGACY_LAYOUT,
  configFile,
  legacyFile,
  userStatePath,
  writeFileAtomic,
} from "../../../shared/interface.ts";
import type { UpgradeDeps } from "../../deps.ts";

/** 归档后缀：搬完留证据，也是「这一份处理过了」的标记（固定名 → 重跑不累积）。 */
const MIGRATED_SUFFIX = ".migrated.bak";

/**
 * 空落盘形态。初始形态一律是**空结构**而不是默认值快照——写全量默认值会把「用户覆盖过哪些键」这个
 * 语义冲掉（文件里每个键都会被读成用户显式提交的）。
 *
 * 配置与用户状态用**版本化**空形：裸 `{}` 会被各自的读面当成缺版本字段的历史文件，而这两份文件的
 * 形态契约里就有 `version`（`server/store` 与 `server/store/impl/middleware-state.ts` 都按它落盘）。
 */
const EMPTY_CONFIG = `${JSON.stringify({ version: 1, servers: [] }, null, 2)}\n`;
const EMPTY_USER_STATE = `${JSON.stringify({ version: 1, disabled: {} }, null, 2)}\n`;

/** 布局的一项。 */
interface LayoutEntry {
  /** 旧文件名（DSH_HOME 根目录下）。 */
  readonly legacy: string;
  /** 目标路径。是**取路径的函数**而不是路径：`DSH_HOME` 在装配期才定，模块加载期取值会落错根。 */
  readonly target: () => string;
  /** 目标与旧文件都不存在时的初始形态。 */
  readonly initial: string;
  /** 用户显式接管了这份落点时为真——整项不动（见 `migrateStorageLayout`）。 */
  readonly takenOver?: (deps: UpgradeDeps) => boolean;
}

/** 单文件布局项：只剩用户数据两项（可再生落点不进迁移，见模块头注释）。 */
const LAYOUT: readonly LayoutEntry[] = [
  {
    legacy: LEGACY_LAYOUT.config,
    target: configFile,
    initial: EMPTY_CONFIG,
    takenOver: (deps) => deps.storePath !== "",
  },
  { legacy: LEGACY_LAYOUT.userState, target: userStatePath, initial: EMPTY_USER_STATE },
];

/**
 * 旧存储 → 新存储布局。逐项独立（一项搬不动不影响其余），但**搬不动都抛出**：迁移没做完而启动照常，
 * 等于让各域按错误的形态去读数据。幂等：目标已存在即处理过，归档名固定、重跑不累积。
 *
 * 用户显式配置了 `storePath` 的那一项**整项不动**——不迁移、不改写、也不建初始形态：
 * 插件继续读用户那个文件，默认落点上的旧文件不是它的数据，搬走或归档都是替用户做主张。
 */
export async function migrateStorageLayout(deps: UpgradeDeps): Promise<void> {
  for (const entry of LAYOUT) {
    if (entry.takenOver !== undefined && entry.takenOver(deps)) continue;
    await settleOne(legacyFile(entry.legacy), entry.target(), entry.initial, deps);
  }
}

/**
 * 落定一项。目标已存在即视为「这一份处理过了」：不覆盖、只把源文件归档——用户可能已经在新位置改过
 * 东西，用旧文件盖回去等于用历史覆盖现在。`initial` 为 null 的落点（项目级配置：缺文件即空
 * store，没有各自的初始形态）不建文件。
 *
 * 项目级 just-in-time 迁移（`./project-layout.ts`）复用本函数：同文件内的 `settleOne` 即同一语义。
 */
export async function settleOne(
  source: string,
  target: string,
  initial: string | null,
  deps: UpgradeDeps,
): Promise<void> {
  if (existsSync(target)) {
    warnIfDowngraded(source, target, deps);
    archive(source);
    return;
  }
  if (!existsSync(source)) {
    if (initial !== null) await writeFileAtomic(target, initial);
    return;
  }
  await writeFileAtomic(target, readSource(source));
  archive(source);
}

/**
 * 目标比旧文件更新才出声：旧文件更新说明有更旧的版本在迁移之后又写过它（降级写入），
 * 该让人知道这次归档丢掉了什么。mtime 只影响**这条文案**，不改变动作。
 */
function warnIfDowngraded(source: string, target: string, deps: UpgradeDeps): void {
  if (!existsSync(source)) return;
  if (statSync(source).mtimeMs <= statSync(target).mtimeMs) return;
  deps.logger.warn(
    `dsh-mcp-manager: 旧存储文件 ${source} 比目标 ${target} 更新——检测到更旧的降级写入，将归档旧文件并保留目标`,
  );
}

/** 常规文件判定（归档多代只跳过常规文件：占位的是目录即改名失败照抛，旧报警保留）。 */
function isRegularFile(path: string): boolean {
  try {
    return statSync(path).isFile();
  } catch {
    return false;
  }
}

/** 读旧文件；读不出来即抛——那是「搬不动」，不该被当成「没有旧数据」。内容一律不解析。 */
function readSource(source: string): string {
  try {
    return readFileSync(source, "utf8");
  } catch (cause) {
    throw new Error(`dsh-mcp-manager: 旧存储文件不可读：${source}`, { cause });
  }
}

/**
 * 归档源文件；本来就没有就什么都不做。首选固定名（`${source}.migrated.bak` =
 * 「这一份处理过了」的标记，幂等语义不变）；该名已存在（降级写入让旧文件重现，
 * 见 warnIfDowngraded）时按 `.2`、`.3`……留多代，不覆盖第一代证据（#903 M-arch）。
 */
function archive(source: string): void {
  if (!existsSync(source)) return;
  let target = `${source}${MIGRATED_SUFFIX}`;
  for (let generation = 2; isRegularFile(target); generation += 1) {
    target = `${source}${MIGRATED_SUFFIX}.${generation}`;
  }
  try {
    renameSync(source, target);
  } catch (cause) {
    throw new Error(`dsh-mcp-manager: 旧存储文件改名失败：${source}`, { cause });
  }
}

/**
 * upgrade 域版本号与版本文件：**存储版本**（`version` 文件里的刻度）与**插件版本**（package.json 里的目标）
 * 在这里相遇，升级链就是把前者逐刻度推到后者——两者分开存放，才区分得开「还没升」与「升完了」。
 */
import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { readTextFile, versionFile, writeFileAtomic } from "../../../shared/interface.ts";

/** 没有版本文件时的起点：从未升级过。 */
const BASELINE_VERSION = "0.0.0";

/** 取不到插件版本时的兜底。读到包清单失败不该阻断启动——升级链空转一轮而已。 */
const UNKNOWN_VERSION = "0.0.0";

/**
 * 向上搜索包根的层数上限。真实形态只差 1 层（产物内联进 `lib/index.js`），白盒单测差 5 层；
 * 不设边界就等于允许一路走到文件系统根，去撞一个与本包无关的 `package.json`。
 */
const PACKAGE_ROOT_MAX_DEPTH = 8;

/**
 * 读存储版本。没有版本文件 = 从未升级过 = 从零跑整条链：每一步都会自己判断有没有它的活要干，
 * 全新安装下只有「落定初始形态」那部分生效，而从更早版本升上来的安装正好借这一轮把该做的做掉。
 */
export async function readStoredVersion(): Promise<string> {
  const text = await readTextFile(versionFile());
  if (text === null) return BASELINE_VERSION;
  const trimmed = text.trim();
  return trimmed === "" ? BASELINE_VERSION : trimmed;
}

/** 写存储版本：一步升级完成即推进一档。写不进去即抛，调用方中止这一次升级、下次从同一步重跑。 */
export async function writeStoredVersion(version: string): Promise<void> {
  await writeFileAtomic(versionFile(), `${version}\n`);
}

/**
 * 本插件当前版本：读包根的 package.json。**不写成常量**——常量与发布版本之间没有任何机制保证同步，
 * 而漂移的那一次会让升级链永远停在旧刻度上（「版本没变」与「升级没做完」外部表现一模一样）。
 *
 * 包根按**最近的一个 `package.json`** 解析而不是固定 `..`：产物形态经 bundle-host 全部内联进
 * `lib/index.js`（上一级即包根），而白盒单测直接加载 `src/server/upgrade/impl/version/index.ts`
 * （五级）；写死层数只有一种形态成立，另一种会让版本静默回落到兜底值。
 */
export function pluginVersion(): string {
  const root = packageRootFrom(dirname(fileURLToPath(import.meta.url)));
  if (root === undefined) return UNKNOWN_VERSION;
  try {
    const parsed: { version?: unknown } = JSON.parse(
      readFileSync(join(root, "package.json"), "utf8"),
    );
    return typeof parsed.version === "string" ? parsed.version : UNKNOWN_VERSION;
  } catch {
    return UNKNOWN_VERSION;
  }
}

/**
 * 从 `fromDir` 向上找最近的含 `package.json` 的目录；走到层数上限仍没有则 undefined。
 * 导出只为本域用例能断言「没有包根」这条边界——对外契约面仍只有 `installUpgrade` / `releaseUpgrade`。
 */
export function packageRootFrom(fromDir: string): string | undefined {
  let current = fromDir;
  for (let depth = 0; depth < PACKAGE_ROOT_MAX_DEPTH; depth += 1) {
    if (existsSync(join(current, "package.json"))) return current;
    const parent = dirname(current);
    if (parent === current) return undefined;
    current = parent;
  }
  return undefined;
}

/**
 * 版本号比较：逐段数值比较。段数不同按缺位补零（`0.3` 等价 `0.3.0`）；预发布后缀（`-rc.1`）不参与
 * 比较——本包的版本序列只用到 `主.次.修订`，为一个不会出现的输入引一套 semver 语义，换来的是又一处
 * 需要跟着上游走的依赖。
 */
export function compareVersions(left: string, right: string): number {
  const a = parseVersion(left);
  const b = parseVersion(right);
  const length = Math.max(a.length, b.length);
  for (let index = 0; index < length; index += 1) {
    const difference = (a[index] || 0) - (b[index] || 0);
    if (difference !== 0) return difference > 0 ? 1 : -1;
  }
  return 0;
}

function parseVersion(text: string): number[] {
  // #903 parseVersion 宽松收口：预发布后缀显式剥离（旧 parseInt 截断碰巧同效，语义隐晦）；
  // 段非纯数字仍归零——未知输入按 0.0.0 起算跑整条链（各步幂等自查），不抛
  // （启动期读盘数据不可信，抛即崩；归零方向恒为 fail-safe）。
  const core = text.split("-")[0] ?? "";
  return core.split(".").map((part) => (/^\d+$/.test(part) ? Number.parseInt(part, 10) : 0));
}

