        [
          "gctx",
          {
            discoveredAt: Date.now(),
            tools: new Map([
              ["use_g", { description: "全局工具", inputSchema: {} }],
              ["other", { description: "无关", inputSchema: {} }],
            ]),
          },
        ],
      ]),
    });
    return new Map([
      [ROOT, unit],
      ["@global", globalUnit],
    ]);
  }

  it("命中项目单元", () => {
