  });

  it("命中 @global 单元", () => {
    const multi = searchCatalogMulti(multiUnits(), [ROOT, "@global"], "use", 10);
    expect(
      multi.results.some((hit) => hit.server === fullServerName("@global", "gctx")),
    ).toBeTruthy();
  });

