      root: "/root-a",
      connections: new Map([
        [
          "cg",
          {
            server: virtual,
            id: undefined,
            handle: undefined,
            status: "connected",
            error: undefined,
            connectedAt: Date.now(),
            readySettled: true,
            everConnected: true,
            disposed: false,
          },
        ],
      ]),
      catalog: new Map(),
      userDisabled: new Set(),
      lastTouchedAt: Date.now(),
      inFlight: new Map(),
      // 单元桩带域外探测字段（catalog/everConnected/disposed）：只供本文件判据，按接缝收窄。
    } as unknown as ProjectUnit);
    manager.middleware = mw;
    const middlewarePayload = () => {
