/**
 * dsh-mcp-manager — unit：visibility 域（#767 笔 1b 交付物 A：模型可见面隐藏）。
 *
 * 覆盖七条判据：名单只取本方单元的 mcp__*（含反例；A1b 另锁四原子工具 ws_mcp_* 豁免）、名单未变不重挂
 * （防自激循环的两道闸）、后注册收敛且旧限制先 dispose、空名单不调用 restrict、disposed/域 disposer
 * 的清理、事件面缺失的降级、装载时的初始全量 reconcile。
 *
 * 直连域门面（`src/server/visibility/interface.ts`）——**不 import src/index.ts**（单元层
 * 导入面越界是已登记存量，新增即判红）。
 */
import { describe, expect, it } from "vitest";
import type { ToolRestriction } from "@deepseek-ai/dsh-tools";
import { startAgentVisibility } from "../../src/server/visibility/interface.ts";
import type { VisibilityEventsPort } from "../../src/server/visibility/interface.ts";
import type { AgentFace } from "../../src/server/shared/interface.ts";
import type { ProjectUnit } from "../../src/server/connection/runtime/interface.ts";

/** 假 agent：restrict 记一笔，返回的摘除器也记一笔（带句柄号，供顺序断言）。 */
function fakeAgent(id: string, log: string[], onChange?: () => (() => void)[]): AgentFace {
  let seq = 0;
  return {
    id,
    tools: {
      restrict(filter: ToolRestriction) {
        seq += 1;
        const handle = `${id}#${seq}`;
        log.push(`restrict:${id}[${[...(filter.deny ?? [])].join("|")}]`);
        // 宿主 restrict 会**同步**发 tools/change：夹具照做，才测得到重入闸。
        if (onChange) for (const hook of onChange()) hook();
        return () => log.push(`dispose:${handle}`);
      },
    },
  };
}

/** 假事件面：三个监听各自可注入、摘除器可观测；`liveAgents` 由调用方给。 */
function makeEvents(liveAgents: () => readonly AgentFace[] = () => []) {
  const handlers: {
    created: ((agent: AgentFace) => void)[];
    disposed: ((agent: { id: string }) => void)[];
    changed: (() => void)[];
  } = { created: [], disposed: [], changed: [] };
  const unhooked: string[] = [];
  const port: VisibilityEventsPort = {
    onAgentCreated: (handler) => {
      handlers.created.push(handler);
      return () => {
        unhooked.push("created");
      };
    },
    onAgentDisposed: (handler) => {
      handlers.disposed.push(handler);
      return () => {
        unhooked.push("disposed");
      };
    },
    onToolsChange: (handler) => {
      handlers.changed.push(handler);
      return () => {
        unhooked.push("changed");
      };
    },
    liveAgents,
  };
  return {
    handlers,
    unhooked,
    port,
  };
}

/**
 * 单元表夹具：本域只读 `unit.connections[*].id`（注册名 `mcp__<id>__` 的前缀来源，见
 * `visibility/impl/mask/index.ts` 的装配循环）——其余 ProjectUnit/ConnectionEntry 字段（ServerConfig、
 * 六态、句柄等）与本域无关，全量构造会把 visibility 测试耦合到无关形状上，故按本仓既有惯例
 * （unit-lifecycle 的 `as unknown as LoaderPort`）做收窄断言，而不用 any。
 */
function unitsWith(...ids: string[]): ReadonlyMap<string, ProjectUnit> {
  return new Map([
    ["/proj", { connections: new Map(ids.map((id) => [`srv-${id}`, { id }])) }],
  ]) as unknown as ReadonlyMap<string, ProjectUnit>;
}

function makeLogger(): { warns: string[]; warn: (message: string) => void } {
  const warns: string[] = [];
  return {
    warns,
    warn: (message: string) => {
      warns.push(message);
    },
  };
}

describe("visibility 域：mcp__* 的模型可见面隐藏", () => {
  it("A1 agent/created：deny 只含「前缀 mcp__ 且 id 属于本方连接池单元」的名字", () => {
    const log: string[] = [];
    const agent = fakeAgent("a1", log);
    const events = makeEvents();
    const names = ["mcp__id-a__echo", "mcp__id-b__ping", "mcp__other__x", "ws_mcp_call"];
    const logger = makeLogger();
    const dispose = startAgentVisibility({
      events: events.port,
      units: unitsWith("id-a"),
      registeredNames: () => names,
      logger,
    });
    events.handlers.created[0](agent);
    // id-b 不在本方单元表里、mcp__other__x 的 id 段不属于任何单元、ws_mcp_call 不是 mcp__ 前缀。
    expect(log).toEqual(["restrict:a1[mcp__id-a__echo]"]);
    expect(logger.warns).toEqual([]);
    dispose();
  });

  it("A1b 四原子工具（ws_mcp_*）一律不在 deny 名单（DOC-A §1 模型可见面）", () => {
    const log: string[] = [];
    const agent = fakeAgent("a1", log);
    const events = makeEvents();
    const names = [
      "ws_mcp_list",
      "ws_mcp_detail",
      "ws_mcp_search",
      "ws_mcp_call",
      "mcp__id-a__echo",
    ];
    const logger = makeLogger();
    const dispose = startAgentVisibility({
      events: events.port,
      units: unitsWith("id-a"),
      registeredNames: () => names,
      logger,
    });
    events.handlers.created[0](agent);
    // 四原子工具是模型唯一入口：只摘 mcp__*，ws_mcp_* 一个都不许进 deny。
    expect(log).toEqual(["restrict:a1[mcp__id-a__echo]"]);
    expect(logger.warns).toEqual([]);
    dispose();
  });

  it("A2a 重入闸：restrict 同步发 tools/change 时不产生第二次 restrict", () => {
    const log: string[] = [];
    const events = makeEvents();
    const agent = fakeAgent("a1", log, () => events.handlers.changed);
    const dispose = startAgentVisibility({
      events: events.port,
      units: unitsWith("id-a"),
      registeredNames: () => ["mcp__id-a__echo"],
      logger: makeLogger(),
    });
    events.handlers.created[0](agent);
    expect(log).toEqual(["restrict:a1[mcp__id-a__echo]"]);
    dispose();
  });

  it("A2b 记忆闸：名单未变的后续 tools/change 不再动限制面", () => {
    const log: string[] = [];
    const events = makeEvents();
    const agent = fakeAgent("a1", log);
    const dispose = startAgentVisibility({
      events: events.port,
      units: unitsWith("id-a"),
      registeredNames: () => ["mcp__id-a__echo"],
      logger: makeLogger(),
    });
    events.handlers.created[0](agent);
    events.handlers.changed[0]();
    events.handlers.changed[0]();
    expect(log).toEqual(["restrict:a1[mcp__id-a__echo]"]);
    dispose();
  });

  it("A3 后注册的 mcp__* 经 tools/change 进名单，且旧限制先被 dispose", () => {
    const log: string[] = [];
    const events = makeEvents();
    const agent = fakeAgent("a1", log);
    const names = ["mcp__id-a__echo"];
    const dispose = startAgentVisibility({
      events: events.port,
      units: unitsWith("id-a"),
      registeredNames: () => names,
      logger: makeLogger(),
    });
    events.handlers.created[0](agent);
    // 第一次 reconcile 之后才注册的新工具（restriction 是调用时刻快照，不在旧快照里）。
    names.push("mcp__id-a__late");
    events.handlers.changed[0]();
    expect(log).toEqual([
      "restrict:a1[mcp__id-a__echo]",
      "dispose:a1#1",
      "restrict:a1[mcp__id-a__echo|mcp__id-a__late]",
    ]);
    dispose();
  });

  it("A4 名单为空：不调用 restrict，但旧的限制仍被 dispose", () => {
    const log: string[] = [];
    const events = makeEvents();
    const agent = fakeAgent("a1", log);
    const names = ["mcp__id-a__echo"];
    const dispose = startAgentVisibility({
      events: events.port,
      units: unitsWith("id-a"),
      registeredNames: () => names,
      logger: makeLogger(),
    });
    events.handlers.created[0](agent);
    names.length = 0;
    events.handlers.changed[0]();
    // 空 filter 会被宿主当场拒：本轮只撤旧的，不新调用 restrict。
    expect(log).toEqual(["restrict:a1[mcp__id-a__echo]", "dispose:a1#1"]);
    dispose();
  });

  it("A5 agent/disposed 撤该 agent 的限制；域 disposer 撤全部并摘三个监听", () => {
    const log: string[] = [];
    const events = makeEvents();
    const a1 = fakeAgent("a1", log);
    const a2 = fakeAgent("a2", log);
    const dispose = startAgentVisibility({
      events: events.port,
      units: unitsWith("id-a"),
      registeredNames: () => ["mcp__id-a__echo"],
      logger: makeLogger(),
    });
    events.handlers.created[0](a1);
    events.handlers.created[0](a2);
    expect(log).toEqual(["restrict:a1[mcp__id-a__echo]", "restrict:a2[mcp__id-a__echo]"]);
    events.handlers.disposed[0]({ id: "a1" });
    expect(log).toEqual([
      "restrict:a1[mcp__id-a__echo]",
      "restrict:a2[mcp__id-a__echo]",
      "dispose:a1#1",
    ]);
    dispose();
    expect(log).toEqual([
      "restrict:a1[mcp__id-a__echo]",
      "restrict:a2[mcp__id-a__echo]",
      "dispose:a1#1",
      "dispose:a2#1",
    ]);
    expect(events.unhooked.sort()).toEqual(["changed", "created", "disposed"]);
  });

  it("A6 降级：事件面缺失 → 不抛、不调用 restrict、只 warn 一次", () => {
    const logger = makeLogger();
    let dispose = () => {};
    expect(() => {
      dispose = startAgentVisibility({
        events: {},
        units: unitsWith("id-a"),
        registeredNames: () => ["mcp__id-a__echo"],
        logger,
      });
    }).not.toThrow();
    expect(logger.warns.length).toBe(1);
    expect(() => dispose()).not.toThrow();
  });

  it("A6c 注册面读口抛错（假 ctx 的 tools 只有 register）→ 降级 no-op、不抛、只 warn 一次", () => {
    const log: string[] = [];
    const events = makeEvents();
    const logger = makeLogger();
    let dispose = () => {};
    expect(() => {
      dispose = startAgentVisibility({
        events: events.port,
        units: unitsWith("id-a"),
        registeredNames: () => {
          throw new TypeError("ctx.tools.schemas is not a function");
        },
        logger,
      });
    }).not.toThrow();
    expect(log).toEqual([]);
    expect(logger.warns.length).toBe(1);
    // 后续 tools/change 仍降级（不抛、不重复喊）。
    events.handlers.changed[0]();
    expect(log).toEqual([]);
    expect(logger.warns.length).toBe(1);
    // agent/created 也走同一条仲裁：注册面读不到就不挂限制（绝不拿空名单去 restrict）。
    events.handlers.created[0](fakeAgent("a1", log));
    expect(log).toEqual([]);
    expect(() => dispose()).not.toThrow();
  });

  it("A6b 服务缺失：liveAgents 缺席/空表 → 无 agent 可挂，不调用 restrict、不告警", () => {
    const log: string[] = [];
    const events = makeEvents(() => []);
    const logger = makeLogger();
    const dispose = startAgentVisibility({
      events: events.port,
      units: unitsWith("id-a"),
      registeredNames: () => ["mcp__id-a__echo"],
      logger,
    });
    expect(log).toEqual([]);
    expect(logger.warns).toEqual([]);
    events.handlers.created[0](fakeAgent("a1", log));
    expect(log).toEqual(["restrict:a1[mcp__id-a__echo]"]);
    dispose();
  });

  it("A7 初始 reconcile：装载时对已经 live 的每个 agent 逐个上限制", () => {
    const log: string[] = [];
    const live = [fakeAgent("live-1", log), fakeAgent("live-2", log)];
    // 活表每次现读都返回**新对象**（同 id），域必须按 id 规范化对象身份，否则记忆恒 miss。
    const events = makeEvents(() => live.map((agent) => ({ ...agent })));
    const dispose = startAgentVisibility({
      events: events.port,
      units: unitsWith("id-a"),
      registeredNames: () => ["mcp__id-a__echo"],
      logger: makeLogger(),
    });
    expect(log).toEqual(["restrict:live-1[mcp__id-a__echo]", "restrict:live-2[mcp__id-a__echo]"]);
    // 名单未变的 tools/change 不得因为「新对象」再挂一次（身份规范化的判据）。
    events.handlers.changed[0]();
    expect(log.length).toBe(2);
    dispose();
    expect(log.length).toBe(4);
  });
});

packages/dsh-mcp-manager/test/unit/upgra.source:
/**
 * dsh-mcp-manager upgrade 域 service 块 —— 装配面：跑链的时机、刻度的推进与不推进、对账与装配标记。
 *
 * 判据面：升级必须在各域装配**之前**跑完（先装配就等于让各域读到旧形态并带着它继续跑）。链本身锁四处：
 * **起点边界**（刻度恰好停在 `fromVersion` 的装机必须执行这一步——唯一的真实升级场景）、
 * **失败不推进**（刻度回写在 `run` 之后，失败即不写，下次从同一步重跑）、**三种落差分开报**
 * （要人去改的地方完全不同，合成一条等于三处都只剩「有出声」）、**装配标记**（重复装配当场抛、
 * release 只复位标记、失败不占住标记）。
 */
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  LEGACY_LAYOUT,
  configFile,
  legacyFile,
  versionFile,
} from "../../../src/server/shared/interface.ts";
import type { UpgradeDeps } from "../../../src/server/upgrade/deps.ts";
import { pendingSteps, reportGap } from "../../../src/server/upgrade/impl/chain/index.ts";
import type { UpgradeStep } from "../../../src/server/upgrade/impl/chain/type.ts";
import { STEPS } from "../../../src/server/upgrade/impl/steps/index.ts";
import { compareVersions, pluginVersion } from "../../../src/server/upgrade/impl/version/index.ts";
import { installUpgrade, releaseUpgrade } from "../../../src/server/upgrade/interface.ts";
import { makeLogger, tempDshHome } from "../../helpers.ts";

let disposeHome: () => void;

beforeEach(() => {
  disposeHome = tempDshHome().dispose;
});

afterEach(() => {
  // 单例标记是模块级状态：用例失败也要复位，否则后续用例会被「只能装配一次」连坐。
  releaseUpgrade();
  disposeHome();
});

/** 步骤表里最高的目标版本：链跑完的刻度应当正好落在它上面。 */
function newestTarget(): string {
  return STEPS.map((step) => step.targetVersion).reduce((newest, version) =>
    compareVersions(version, newest) > 0 ? version : newest,
  );
}

/** 装配一次升级域（链在装配期跑完）。 */
async function assemble(overrides: Partial<UpgradeDeps> = {}) {
  const logger = overrides.logger ?? makeLogger();
  const deps: UpgradeDeps = { logger, storePath: "", ...overrides };
  await installUpgrade(deps);
  return { logger, deps };
}

/** 种一份刻度（父目录可能还不存在）。 */
function seedClock(version: string): void {
  mkdirSync(dirname(versionFile()), { recursive: true });
  writeFileSync(versionFile(), `${version}\n`, "utf8");
}

/** 合成一步：只用来断言排序与起点边界，不做任何磁盘动作。 */
function step(fromVersion: string, targetVersion: string): UpgradeStep {
  return { fromVersion, targetVersion, run: () => Promise.resolve() };
}

describe("装配期跑链", () => {
  it("装配返回时刻度已落在步骤表最后一步的目标版本，初始形态也已落定", async () => {
    await assemble();

    expect(readFileSync(versionFile(), "utf8").trim()).toBe(newestTarget());
    expect(existsSync(configFile())).toBe(true);
  });

  it("刻度已到目标版本的存储不再重跑步骤（否则每次启动都会拿旧文件盖回用户改过的新数据）", async () => {
    seedClock(newestTarget());
    const legacy = legacyFile(LEGACY_LAYOUT.config);
    writeFileSync(legacy, '{"legacy":true}\n', "utf8");

    await assemble();

    // 判据不能只看「新布局的内容没被覆盖」——步骤本身幂等，恒跑也绿；旧文件仍在原地才是「一次都没跑」的证据。
    expect(existsSync(legacy)).toBe(true);
    expect(existsSync(`${legacy}.migrated.bak`)).toBe(false);
    expect(existsSync(configFile())).toBe(false);
  });

  // 起点边界是唯一真实的升级场景：装机刻度恰好停在这一步的起点。边界写成 `> 0` 时这一步整个跳过，
  // 而外部表现是「升级后配置读空、旧文件还躺在 home 根目录」——故判据必须落在「旧文件被搬走了」上。
  it("刻度停在 fromVersion 的装机必须执行这一步", async () => {
    seedClock(STEPS[0].fromVersion);
    const legacy = legacyFile(LEGACY_LAYOUT.config);
    writeFileSync(legacy, '{"legacy":true}\n', "utf8");

    await assemble();

    expect(readFileSync(configFile(), "utf8")).toBe('{"legacy":true}\n');
    expect(existsSync(legacy)).toBe(false);
    expect(readFileSync(`${legacy}.migrated.bak`, "utf8")).toBe('{"legacy":true}\n');
    expect(readFileSync(versionFile(), "utf8").trim()).toBe(newestTarget());
  });

  it("链失败即中止装配，并且**不推进刻度**：清障后从同一步重跑才写完", async () => {
    const legacy = legacyFile(LEGACY_LAYOUT.config);
    // 旧文件读不出来（同名目录）：这一步必然失败，而刻度文件本身的落点完全可写——
    // 于是「刻度没被写」是这次失败的直接后果，不是障碍物的副作用。
    mkdirSync(legacy, { recursive: true });

    await expect(assemble()).rejects.toThrow(`存储升级到 ${newestTarget()} 失败`);

    expect(existsSync(versionFile())).toBe(false);
    // 失败点之前没有任何一项落定：中止不是「跳过失败的那项继续跑」。
    expect(existsSync(configFile())).toBe(false);

    // 清障后重试：失败没有占住「已装配」，刻度此刻还不存在，只有真的重跑完链它才会落到目标版本。
    rmSync(legacy, { recursive: true, force: true });
    writeFileSync(legacy, '{"legacy":true}\n', "utf8");
    await assemble();

    expect(readFileSync(versionFile(), "utf8").trim()).toBe(newestTarget());
    expect(readFileSync(configFile(), "utf8")).toBe('{"legacy":true}\n');
  });

  // 刻度是「这一步做完了」的凭证：回写不进去却继续跑，下次启动会从一个不存在的刻度重来。
  it("步骤跑完但刻度回写失败即中止装配", async () => {
    mkdirSync(versionFile(), { recursive: true });
    writeFileSync(join(versionFile(), "占位"), "", "utf8");

    await expect(assemble()).rejects.toThrow(`存储版本号回写失败（${newestTarget()}）`);
  });
});

describe("装配期的对账用真实插件版本", () => {
  /**
   * 判据刻意不写成「装配后有没有 warn」这种与包版本无关的形态，而是让用例自己算一遍落差——把
   * `pluginVersion()` 换回常量、或把对账挪到链之前，这条算术都对不上（前者的消息里不会出现真实版本号，
   * 后者报的是「存储版本 0.0.0 落后」，不含步骤表的目标版本）。
   *
   * 本包尚未发版时步骤表（0.2.5）超前于 package.json，此刻的期望是「一条不同步 warn」；发版对齐后
   * 期望自动变成「零 warn」——这正是对账要报的那种落差，不是需要改用例的例外。
   */
  it("落差有就出声、没有就零噪音，且消息里同时出现步骤表目标与真实插件版本", async () => {
    const logger = makeLogger();
    const plugin = pluginVersion();

    await assemble({ logger });

    expect(logger.warns).toHaveLength(compareVersions(newestTarget(), plugin) === 0 ? 0 : 1);
    if (compareVersions(newestTarget(), plugin) !== 0) {
      expect(logger.warns[0]).toContain(newestTarget());
      expect(logger.warns[0]).toContain(plugin);
    }
  });
});

describe("链跑完后的版本对账：三种落差分开报", () => {
  // 三态的判据必须分别给：只用「装配后有没有 warn」这一条，把三种落差合并成一条也绿，
  // 而它们要人去改的地方完全不同（补步骤 / 改 package.json / 换回正确的装机）。
  it("刻度与插件版本一致：一个字的诊断都不出（对账不该成为日常噪音）", () => {
    const logger = makeLogger();

    reportGap(newestTarget(), newestTarget(), logger);

    expect(logger.warns).toEqual([]);
  });

  it("刻度落后于插件版本：报「缺少对应的升级步骤」（改的是步骤表）", () => {
    const logger = makeLogger();

    reportGap("0.1.0", "0.3.0", logger);

    expect(logger.warns).toHaveLength(1);
    expect(logger.warns[0]).toContain("存储版本 0.1.0 落后于插件版本 0.3.0");
    expect(logger.warns[0]).toContain("缺少对应的升级步骤");
  });

  it("刻度超前而步骤表也超前：报「步骤表与 package.json 不同步」（改的是 package.json）", () => {
    const logger = makeLogger();

    reportGap("0.3.0", "0.2.3", logger);

    expect(logger.warns).toHaveLength(1);
    expect(logger.warns[0]).toContain(`升级链的目标版本 ${newestTarget()} 高于插件版本 0.2.3`);
    expect(logger.warns[0]).toContain("步骤表与 package.json 不同步");
  });

  it("刻度超前而步骤表没超前：报「不回退」（装的是更旧的包，改的是装机本身）", () => {
    const logger = makeLogger();

    reportGap("0.3.0", newestTarget(), logger);

    expect(logger.warns).toHaveLength(1);
    expect(logger.warns[0]).toContain("本插件的升级链不回退");
  });
});

describe("待办步：按目标版本升序，刻度停在起点才算待办", () => {
  it("不按声明顺序执行：声明倒序的两步也按目标版本升序返回", () => {
    const declared = [step("0.2.5", "0.3.0"), step("0.0.0", "0.2.5")];

    expect(pendingSteps(declared, "0.0.0").map((entry) => entry.targetVersion)).toEqual([
      "0.2.5",
      "0.3.0",
    ]);
  });

  it("刻度已到某步起点之后即跳过该步（含恰好停在起点时必须执行的边界）", () => {
    const table = [step("0.0.0", "0.2.5"), step("0.2.5", "0.3.0")];

    expect(pendingSteps(table, "0.2.5").map((entry) => entry.targetVersion)).toEqual(["0.3.0"]);
    expect(pendingSteps(table, "0.3.0")).toEqual([]);
    expect(pendingSteps(table, "0.0.0")).toHaveLength(2);
  });
});

describe("生命周期", () => {
  it("重复装配当场抛错；release 幂等、不清掉已落盘的迁移结果，之后可以再装配", async () => {
    await assemble();
    // 说清是哪个域拒绝的：`/只能装配一次/` 这种宽判据在「装配体被整段短路」时也会绿。
    await expect(assemble()).rejects.toThrow("dsh-mcp-manager: upgrade 域只能装配一次");

    const before = readFileSync(configFile(), "utf8");
    releaseUpgrade();
    releaseUpgrade();
    // 本域没有需要在卸载时收回的东西：链已经写完的文件不会被卸载动作改回去。
    expect(readFileSync(configFile(), "utf8")).toBe(before);

    await expect(assemble()).resolves.toBeDefined();
  });
});

